function normalizedExerciseName(name){return String(name||'').trim().replace(/\s+/g,' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr')}
function canonicalExerciseName(name){const clean=String(name||'').trim().replace(/\s+/g,' '),alias=EXERCISE_NAME_ALIASES[normalizedExerciseName(clean)];return alias||clean}
function exerciseSlug(name){return normalizedExerciseName(canonicalExerciseName(name)).replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'')}
function exerciseStableId(name,customExercises){const list=Array.isArray(customExercises)?customExercises:(typeof state!=='undefined'&&Array.isArray(state.customExercises)?state.customExercises:[]),target=normalizedExerciseName(canonicalExerciseName(name)),custom=list.find(x=>normalizedExerciseName(x.name)===target);return custom?'custom:'+custom.id:'exercise:'+exerciseSlug(canonicalExerciseName(name))}
function exerciseKey(ex){return ex?.exerciseId||exerciseStableId(ex?.name||ex)}
