function planFor(day,w=state.profile.week){const custom=state.planOverrides?.[w]?.[day];return custom?custom.map(e=>resolvePlannedExerciseLoad(e,w)):defaultPlanFor(day,w)}
function ensurePlanOverride(w,day){state.planOverrides||={};state.planOverrides[w]||={};if(!Array.isArray(state.planOverrides[w][day]))state.planOverrides[w][day]=planFor(day,w).map(e=>({...clone(e),loadMode:'auto'}));return state.planOverrides[w][day]}
function resetPlanOverride(w,day){if(!state.planOverrides?.[w]?.[day])return;delete state.planOverrides[w][day];if(!Object.keys(state.planOverrides[w]).length)delete state.planOverrides[w];save();render();toast('Séance remise au programme prévu.')}
function setDayAssignment(w,day,value){state.dayOverrides||={};const week=state.dayOverrides[w]||={};const def=day<6?day:'rest';if(value===def)delete week[day];else week[day]=value;if(!Object.keys(week).length)delete state.dayOverrides[w];if(state.planOverrides?.[w]?.[day]){delete state.planOverrides[w][day];if(!Object.keys(state.planOverrides[w]).length)delete state.planOverrides[w]}save();render();toast('Semaine '+w+' mise à jour · la séance de ce jour repart du programme prévu.');}
function resetWeekDays(w){if(state.dayOverrides?.[w]){delete state.dayOverrides[w];save();render();toast('Semaine '+w+' remise à l’organisation normale.')}}
function organizeWeekModal(w){if(activeGeneratedProgram()){showModal('Organisation pilotée par Coach.',`<p class="small muted">Cette semaine appartient à ton programme généré. Les jours d’entraînement viennent de tes disponibilités Coach pour garder une structure cohérente sur tout le cycle.</p><div class="note">Tu peux toujours modifier les exercices d’une séance. Pour changer les jours ou le nombre de séances, régénère le programme avec tes nouvelles disponibilités.</div>`,[{label:'Fermer',kind:'outline',fn:closeModal},{label:'Modifier mes paramètres',fn:()=>{closeModal();coachSetupModal()}}]);return}showModal('Organiser la semaine '+w+'.',`<p class="small muted" style="margin-bottom:18px">Choisis quelle séance — ou repos — pour chaque jour. Ça ne change que la semaine ${w} : les autres semaines gardent leur organisation normale.</p><div class="stack">${WEEKDAYS.map((name,day)=>{const t=templateForDay(day,w);return `<div class="field"><label for="assign${day}">${name}</label><select id="assign${day}" data-input="assignDay" data-day="${day}">${program.map((p,i)=>`<option value="${i}" ${t===i?'selected':''}>${esc(p.name)}</option>`).join('')}<option value="rest" ${t===null?'selected':''}>Repos</option></select></div>`}).join('')}</div>${state.dayOverrides?.[w]?`<button class="link-btn" style="margin-top:16px" data-action="resetWeek:${w}">${icon('history')}Réinitialiser l’organisation de la semaine ${w}</button>`:''}`,[{label:'Fermer',fn:closeModal}],true)}
function workload(sets){return sets.reduce((sum,s)=>sum+s.load*s.reps,0)}
function draftStats(){const list=state.draft?.exercises||[];return{done:list.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0),total:list.reduce((n,e)=>n+e.sets.length,0)}}
function weeklyHistory(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));const end=new Date(d);end.setDate(end.getDate()+7);return state.history.filter(h=>new Date(h.date)>=d&&new Date(h.date)<end)}
function toast(msg){clearTimeout(toastTimeout);$('#toast').textContent=msg;$('#toast').classList.remove('hidden');toastTimeout=setTimeout(()=>$('#toast').classList.add('hidden'),3600)}
function btn(label,action,kind='primary',ic=''){return `<button class="btn btn-${kind}" data-action="${action}">${label}${ic?icon(ic):''}</button>`}
function intro(title,subtitle,right=''){return `<div class="page-intro"><div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`}
function empty(ic,title,text){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${text}</p></div>`}
const TABINFO=[['home','grid','Tableau de bord','Accueil'],['program','calendar','Programme','Programme'],['workout','dumbbell','Ma séance','Séance'],['progress','chart','Progression','Progrès'],['settings','settings','Réglages','Réglages']];
function shell(){const brand=`<span class="brand-symbol">${icon('dumbbell')}</span><span class="brand-name">MUSCU<span class="orange">.</span><small>COACH PRO</small></span>`;$('.sidebar').innerHTML=`<a class="brand" href="#home" aria-label="Accueil Muscu Coach Pro">${brand}</a><div class="nav-label">TON ESPACE ATHLÈTE</div><nav class="nav-list" aria-label="Navigation principale">${TABINFO.map(([id,i,name])=>`<button class="nav-btn" data-tab="${id}">${icon(i)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-cycle"><div class="row between"><span class="eyebrow muted">CYCLE ACTUEL</span>${icon('bolt')}</div><p id="sidePhase"></p><div class="mini-progress"><i id="sideProgress"></i></div></div><button class="profile-btn" data-tab="settings"><span class="avatar" id="avatar"></span><span><b id="profileName"></b><small>Prise de masse & force</small></span></button></div>`;$('.topbar').innerHTML=`<a class="brand" href="#home">${brand}</a><div class="breadcrumb">Mon espace <span style="padding-left:10px">/</span><b id="crumb"></b></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</span><span class="pill orange">${icon('bolt')}<span id="weekBadge"></span></span><button class="icon-btn" data-action="help" aria-label="Comprendre les repères">${icon('info')}</button></div>`;$('.mobile-nav').innerHTML=TABINFO.map(([id,i,,name])=>`<button class="nav-btn" data-tab="${id}">${icon(i)}<span>${name}</span></button>`).join('');}
function updateShell(){if($('.top-date'))$('.top-date').textContent=fullDateLabel();document.body.classList.toggle('reduced',!state.preferences.motion);$('#weekBadge').textContent=`Semaine ${state.profile.week}`;$('#sidePhase').textContent=phase().short+' · S'+state.profile.week;$('#sideProgress').style.width=Math.min(100,state.profile.week/Math.max(1,cycleWeekCount())*100)+'%';$('#avatar').textContent=state.profile.name.slice(0,1).toUpperCase();$('#profileName').textContent=state.profile.name;$('#crumb').textContent=TABINFO.find(t=>t[0]===tab)[2];$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.classList.contains('nav-btn')){if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}})}
function navigate(next,{scroll=true}={}){if(!TABINFO.some(t=>t[0]===next))return;if(next==='home'){selectionMode='auto';selectedDay=todayPlanDay()}tab=next;render();if(scroll)window.scrollTo({top:0,behavior:'instant'});try{history.replaceState(null,'','#'+tab)}catch{} }
function render(){syncCalendar(false);updateShell();const main=$('#view');main.innerHTML=({home:homeView,program:programView,workout:workoutView,progress:progressView,settings:settingsView,nutrition:()=>nutritionView()})[tab]();main.classList.remove('page-enter');void main.offsetWidth;main.classList.add('page-enter');renderTimer();if(tab==='workout')$('#exerciseTabs .active')?.scrollIntoView({block:'nearest',inline:'center'});if(tab==='program')$('#weekSelector .active')?.scrollIntoView({block:'nearest',inline:'center'});}
function homeView(){const ph=phase(),wk=weeklyHistory(),totalVolume=state.history.reduce((n,h)=>n+workload(h.sets),0),cal=ph.kind==='test';return intro(`Prêt, ${esc(state.profile.name)} <span class="orange">?</span>`,`${fullDateLabel()} · Un objectif, une séance à la fois.`,`<span class="pill">${icon('target')} Prise de masse</span>`)+homeHeroHTML()+weekSummaryExtras()+`
${cal?`<div class="calibration-banner"><div class="row">${icon('target')}<div><b>${state.profile.week===0?'Tes fondations sont déjà là.':'Fais le point sur tes repères.'}</b><p>${state.tests.length} tests enregistrés · ${ph.desc}</p></div></div>${btn('Voir mes références','showRefs','outline')}</div>`:''}
<div class="metrics stagger"><div class="metric"><span class="metric-icon">${icon('dumbbell')}</span><div><strong>${state.history.length}</strong><p>Séances enregistrées</p></div></div><div class="metric"><span class="metric-icon">${icon('weight')}</span><div><strong>${totalVolume>=1000?fmt(totalVolume/1000):fmt(totalVolume)} <small>${totalVolume>=1000?'t':'kg'}</small></strong><p>Volume renseigné cumulé</p></div></div><div class="metric"><span class="metric-icon">${icon('target')}</span><div><strong>${fmt(state.profile.weight)} <small>kg</small></strong><p>Poids du corps</p></div></div></div>
<div class="home-lower"><section class="card"><div class="row between card-head"><h2>Tes repères de force</h2><button class="link-btn" data-action="showRefs">Voir tout ${icon('up')}</button></div>${['Développé couché','Développé militaire','Tractions lestées'].map((name,i)=>{const t=latestTest(name);return `<div class="strength-row"><span class="ex-index">0${i+1}</span><div class="strength-info"><b>${name}</b><p>${t?`${fmt(t.load)} kg${name==='Tractions lestées'?' de lest':''} × ${t.reps} reps`:'À renseigner'} · e1RM${name==='Tractions lestées'?' total':''}</p></div><strong>${t?fmt(e1rm(t)):'—'}<small> kg</small></strong></div>`}).join('')}</section><section class="card block-card"><div class="row between"><span class="eyebrow" style="color:var(--blue)">BLOC ${ph.code} / 08</span><span class="small muted">S${state.profile.week} / 20</span></div><h2 class="block-name">${ph.name}</h2><p class="block-weeks">${ph.desc}</p><div class="track" aria-hidden="true">${Array.from({length:20},(_,i)=>`<i class="${i<state.profile.week?'past':i===state.profile.week?'now':''}"></i>`).join('')}</div><button class="link-btn" data-action="showCycle">Explorer mon cycle ${icon('arrow')}</button></section></div>
<div class="section-heading"><h2>Le travail accompli</h2><button class="link-btn" data-action="showHistory">Historique ${icon('up')}</button></div><section class="card">${state.history.length?historyRows(state.history.slice(-2).reverse()):empty('history','La première séance donne le ton.','Valide tes séries pendant l’entraînement. Ton bilan et tes prochaines charges apparaîtront ici.')}</section>`;}
function coachBannerHTML(){const p=activeGeneratedProgram();if(!p)return `<section class="coach-banner"><div><span class="eyebrow orange">COACH ADAPTATIF</span><h2>Construis ton programme autour de toi.</h2><p>Objectif, poids cible, rythme de progression, disponibilités et priorités musculaires. Le moteur génère ensuite ton cycle et le synchronise avec Supabase.</p></div><button class="btn btn-primary" data-action="coachSetup">Créer mon programme ${icon('arrow')}</button></section>`;const pace=p.goalSnapshot?.gainPace?.targetBodyweightPctPerWeek,days=p.inputSnapshot?.availability?.daysPerWeek||weeklySessionTarget();return `<section class="coach-banner active"><div><span class="eyebrow orange">PROGRAMME COACH ACTIF</span><h2>${fmt(p.goalSnapshot?.currentWeightKg)} → ${fmt(p.goalSnapshot?.targetWeightKg)} kg</h2><p>${days} séances/semaine · ${pace!=null?fmt(pace,2)+' % du poids/semaine · ':''}${p.weeks.length} semaines · génération par règles V1, sans IA.</p></div><button class="btn btn-outline" data-action="coachSetup">Modifier mon programme ${icon('edit')}</button></section>`}
function programView(){const phases=cyclePhases(),weeks=cycleWeekNumbers(),ph=phase(previewWeek);return intro('Ton plan de jeu.','Organise tes séances et personnalise chaque mouvement avant de le lancer.',`<button class="icon-btn" data-action="help" aria-label="Comprendre le cycle">${icon('info')}</button>`)+coachBannerHTML()+`<div class="row between wrap" style="margin-bottom:20px"><div class="segmented"><button class="seg-btn ${programMode==='sessions'?'active':''}" data-action="programMode:sessions">Les séances</button><button class="seg-btn ${programMode==='cycle'?'active':''}" data-action="programMode:cycle">Le cycle complet</button></div><span class="pill orange">Semaine actuelle : ${state.profile.week}</span></div>`+(programMode==='cycle'?`<div class="cycle-timeline">${phases.map(p=>`<article class="phase-row ${state.profile.week>=p.from&&state.profile.week<=p.to?'current':''}"><div class="phase-range">${p.from===p.to?'S'+p.from:p.from+'–'+p.to}</div><div style="flex:1"><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p></div><button class="icon-btn" data-action="preview:${p.from}" aria-label="Voir ${esc(p.name)}">${icon('chevron')}</button></article>`).join('')}</div>`:`<div class="week-selector" id="weekSelector" aria-label="Semaine à consulter">${weeks.map(w=>`<button class="week-tile ${w===previewWeek?'active':''} ${w===state.profile.week?'current':''}" data-action="preview:${w}" aria-pressed="${w===previewWeek}"><small>SEM.</small>${String(w).padStart(2,'0')}</button>`).join('')}</div><div class="plan-preview-label"><span>${esc(ph.name)}${previewWeek!==state.profile.week?' · Aperçu':''}</span><div class="row" style="gap:14px">${previewWeek!==state.profile.week?`<button class="link-btn orange" data-action="setWeek:${previewWeek}">Choisir cette semaine ${icon('arrow')}</button>`:''}<button class="link-btn" data-action="exerciseLibrary">${icon('list')}Bibliothèque d’exercices</button><button class="link-btn" data-action="organizeWeek">${icon('edit')}${activeGeneratedProgram()?'Mes disponibilités':'Organiser ma semaine'}</button></div></div>${ph.kind==='test'?`<div class="note" style="margin-bottom:16px">${icon('info')}${esc(ph.name)} : utilise cette semaine pour fixer ou rafraîchir tes charges sur les mouvements concernés.</div>`:''}<div class="program-grid stagger">${WEEKDAYS.map((_,i)=>programDayHTML(i,previewWeek)).join('')}</div>`)}
function workoutView(){const d=state.draft;if(!d){const wk=state.profile.week||1,meta=sessionMetaForDay(selectedDay,wk),exs=meta?planFor(selectedDay,wk):[];return intro('Entre dans ta séance.','Tes séries, tes charges, ton rythme.')+`<div class="session-overview"><section class="card big-start"><div class="row between"><span class="pill orange">${WEEKDAYS[selectedDay]}</span><span class="eyebrow muted">${meta?esc(meta.focus):'Repos programmé'}</span></div><h2>${meta?meta.name.replace(' + ','<br><span class="orange">+ '):'JOUR DE<br><span class="orange">REPOS</span>'}</span></h2><p class="muted small">${meta?exs.length+' exercices · '+exs.reduce((n,e)=>n+e.sets.length,0)+' séries':'Aucune séance programmée ce jour.'}</p><div class="spacer"></div>${meta?`<div class="stack">${btn('Modifier / réorganiser','editCurrentPlan:'+selectedDay,'outline','edit')}${btn('Lancer ma séance','start:'+selectedDay,'primary','play')}</div>`:''}<div class="divider"></div><label for="chooseDay">Choisir un autre jour</label><select id="chooseDay" data-input="chooseDay">${WEEKDAYS.map((name,i)=>{const m=sessionMetaForDay(i,wk);return `<option value="${i}" ${i===selectedDay?'selected':''}>${name} · ${m?esc(m.name):'Repos'}</option>`}).join('')}</select></section><section class="card"><div class="card-head"><h2>Tout est prêt.</h2></div><div class="divider"></div><div class="stack"><div class="row">${icon('save','orange')}<div><b class="small">Reprise automatique</b><p class="small muted">Tes saisies restent en mémoire.</p></div></div><div class="row">${icon('timer','orange')}<div><b class="small">Repos synchronisé</b><p class="small muted">Il démarre après une série validée.</p></div></div><div class="row">${icon('chart','orange')}<div><b class="small">La suite se prépare</b><p class="small muted">Un bilan et tes prochaines charges.</p></div></div></div><div class="note" style="margin-top:27px">${icon('info')}Renseigne uniquement ce que tu réalises. Une série n’est enregistrée qu’après validation.</div></section></div>`}
const e=d.exercises[d.index],stats=draftStats(),last=lastSets(e.name),complete=e.sets.every(s=>s.done);return `<div class="workout-topline"><div><div class="eyebrow muted">${WEEKDAYS[d.day]} · SEMAINE ${d.week}</div><div class="row" style="margin-top:6px">${icon('clock','orange')}<span class="elapsed" id="elapsed">${timeStr((Date.now()-d.started)/1000)}</span><span class="micro muted">en cours</span></div></div><div class="row workout-actions">${btn('Adapter','adapt','outline','edit')}${btn('Terminer','finish','primary','check')}${btn('Annuler la séance','discard','outline','close')}</div></div><div class="workout-layout"><div><div class="exercise-tabs" id="exerciseTabs" aria-label="Exercices de la séance">${d.exercises.map((ex,i)=>`<button class="ex-tab ${i===d.index?'active':''} ${ex.sets.every(s=>s.done)?'complete':''}" data-action="exercise:${i}" aria-label="${i+1}. ${esc(ex.name)}" aria-pressed="${i===d.index}">${ex.sets.every(s=>s.done)?'✓':String(i+1).padStart(2,'0')}</button>`).join('')}</div><article class="card active-exercise"><div class="row between"><span class="eyebrow orange">EXERCICE ${String(d.index+1).padStart(2,'0')} / ${String(d.exercises.length).padStart(2,'0')}</span><button class="icon-btn" data-action="exerciseInfo" aria-label="Voir les consignes et les repères">${icon('info')}</button></div><h2>${esc(e.name)}</h2><div class="target-chips"><span class="pill">${e.sets.length} séries</span><span class="pill">${esc(e.reps)} reps</span><button class="pill" data-action="help" style="min-height:0">RIR ${e.rir}</button><button class="pill orange" data-action="restSettings" style="min-height:0">${icon('timer')}Séries : ${timeStr(e.rest)}</button><button class="pill orange" data-action="restSettings" style="min-height:0">Entre exos : ${timeStr(exerciseRestDuration(e))}</button>${e.tag.startsWith('superset')?`<span class="pill blue">${esc(e.method)}</span>`:''}</div><div class="set-grid header" aria-hidden="true"><span>#</span><span style="text-align:center">${e.name==='Tractions lestées'?'Lest · kg':'Charge · kg'}</span><span style="text-align:center">Reps</span><span style="text-align:center">RIR</span><span style="text-align:center">Fait</span></div>${e.sets.map((s,i)=>`<div class="set-grid set-item ${s.done?'done':''} ${i===e.sets.findIndex(x=>!x.done)?'current':''}" data-setrow="${i}"><div class="set-no" title="${esc(s.label)}">${i+1}</div>${['load','reps','rir'].map(k=>`<input aria-label="Série ${i+1}, ${k==='load'?'charge en kilogrammes':k==='reps'?'répétitions':'RIR'}" type="number" inputmode="decimal" min="0" ${k==='rir'?'max="5"':k==='reps'?'max="100"':'max="2000"'} step="${k==='reps'?'1':k==='rir'?'.5':'.25'}" value="${s[k]}" data-set="${i}" data-field="${k}" ${s.done?'disabled':''}>`).join('')}<button class="set-check" data-action="check:${i}" aria-label="${s.done?'Annuler la validation':'Valider'} de la série ${i+1}" aria-pressed="${!!s.done}">${icon('check')}</button></div>`).join('')}<div class="set-management"><button class="link-btn" data-action="addSet">${icon('plus')}Ajouter ${e.tag.startsWith('superset')?'une paire':'une série'}</button><button class="link-btn" data-action="removeSet" ${e.sets.length<=1?'disabled':''}>Retirer ${e.tag.startsWith('superset')?'une paire':'une série'}</button></div><div class="exercise-tools"><button class="link-btn" data-action="copyLoad">${icon('edit')} Copier la 1re charge</button><button class="link-btn" data-action="restStart">${icon('timer')} Lancer le repos</button></div>${exerciseMemoryHTML(e)}<div class="training-notes">${last.length?`<b>La dernière fois</b> · ${last.map(s=>fmt(s.load)+' kg × '+s.reps).join(' / ')}`:e.calibrated?'<b>Point de départ</b> · Une proposition à ajuster selon ton ressenti.':'<b>Charge à régler</b> · Aucune référence pour cet exercice. Renseigne ta charge avant de valider.'}${e.name==='Tractions lestées'?'<br>Saisis uniquement le lest ajouté. Ton poids de corps est pris en compte pour l’estimation.':''}${e.method.includes('back-off')?'<br>'+e.sets.map(s=>s.label+' : '+s.min+'–'+s.max+' reps').join(' · '):''}</div></article><div class="exercise-navigate"><button class="btn btn-outline" data-action="exercise:${d.index-1}" ${d.index===0?'disabled':''}>${icon('back')}Précédent</button><button class="btn ${complete?'btn-primary':'btn-outline'}" data-action="${d.index===d.exercises.length-1?'finish':'exercise:'+(d.index+1)}">${d.index===d.exercises.length-1?'Bilan de séance':'Exercice suivant'}${icon('arrow')}</button></div><div class="live-progress"><div class="row between"><span>${stats.done} / ${stats.total} séries validées</span><span>${Math.round(stats.done/stats.total*100)} %</span></div><div class="mini-progress"><i style="width:${stats.done/stats.total*100}%"></i></div></div><button class="link-btn" data-action="discard" style="margin-top:25px">Abandonner cette séance</button></div><aside class="card queue-card"><span class="eyebrow muted">DANS TA SÉANCE</span>${d.exercises.map((ex,i)=>`<button class="queue-item ${i===d.index?'current':''}" data-action="exercise:${i}">${icon(ex.sets.every(s=>s.done)?'check':'dumbbell')}<span>${esc(ex.name)}</span><small>${ex.sets.filter(s=>s.done).length}/${ex.sets.length}</small></button>`).join('')}<div class="note" style="margin-top:20px">Tes séries sont conservées même si tu quittes cet écran.</div></aside></div>`;}
function historyRows(items){return items.map(h=>{const c=h.completion,ratio=c&&c.total?c.done/c.total:1,partial=ratio<1;return `<details class="history-row"><summary><div class="history-date">${new Date(h.date).getDate()}<small>${new Date(h.date).toLocaleDateString('fr-FR',{month:'short'})}</small></div><div class="history-info"><b>${esc(h.name)}</b>${partial?`<span class="pill ${ratio>=0.7?'orange':'red'}" style="margin-left:6px">${c.done}/${c.total}</span>`:''}${h.records?.length?'<span class="record-badge">'+icon('trophy')+h.records.length+' record'+(h.records.length>1?'s':'')+'</span>':''}<p>${h.sets.length} séries${h.duration?' · '+Math.max(1,Math.round(h.duration/60))+' min':''}${h.week!=null?' · S'+h.week:''}</p></div><span class="history-vol">${fmt(workload(h.sets)/1000)} t</span>${icon('chevron')}</summary><div class="history-detail">${compactResults(h)}<button class="btn btn-outline btn-wide" style="margin-bottom:14px" data-action="showRecap:${esc(h.id)}">Ouvrir le bilan complet ${icon('arrow')}</button><button class="link-btn" style="color:#f7a5a5" data-action="deleteHistory:${esc(h.id)}">Supprimer cette séance</button></div></details>`}).join('')}
function progressPoints(name){const id=exerciseStableId(name),points=state.tests.filter(t=>(t.exerciseId||exerciseStableId(t.ex))===id).map(t=>({date:t.date,value:e1rm(t),type:'Test'}));for(const h of state.history){const sets=h.sets.filter(s=>(s.exerciseId||exerciseStableId(s.name))===id);if(sets.length)points.push({date:h.date,value:Math.max(...sets.map(s=>e1rm({...s,ex:canonicalExerciseName(s.name||name),exerciseId:id,bw:h.bodyWeight||state.profile.weight}))),type:'Séance'})}return points.sort((a,b)=>(a.date?new Date(a.date).getTime():0)-(b.date?new Date(b.date).getTime():0)).slice(-12)}
function chartHTML(name){const data=progressPoints(name);if(!data.length)return empty('chart','Ta courbe commence avec un repère.','Ajoute un test ou termine une séance sur cet exercice pour suivre ton évolution.');const values=data.map(d=>d.value),min=Math.max(0,Math.floor(Math.min(...values)*.85/5)*5),max=Math.max(min+10,Math.ceil(Math.max(...values)*1.08/5)*5),width=620,height=240,left=45,right=595,top=20,bottom=198,point=(d,i)=>({x:data.length===1?320:left+(right-left)*i/(data.length-1),y:bottom-(d.value-min)/(max-min)*(bottom-top)}),pts=data.map(point),path=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ');return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Évolution du maximum estimé pour ${esc(name)}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ff7947" stop-opacity=".18"/><stop offset="100%" stop-color="#ff7947" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const y=top+(bottom-top)*i/3;return `<line class="chart-grid" x1="${left}" x2="${right}" y1="${y}" y2="${y}"/><text class="chart-axis" x="0" y="${y+4}">${fmt(max-(max-min)*i/3,0)}</text>`}).join('')}${pts.length>1?`<path d="${path}L${right},${bottom}L${left},${bottom}Z" fill="url(#chartFill)"/><path class="chart-line" d="${path}"/>`:''}${pts.map((p,i)=>`<circle class="chart-point" cx="${p.x}" cy="${p.y}" r="5" tabindex="0" role="button" aria-label="${data[i].type} ${esc(dateFr(data[i].date))}, ${fmt(data[i].value)} kilogrammes" data-action="chartPoint:${i}"><title>${fmt(data[i].value)} kg · ${dateFr(data[i].date)}</title></circle>`).join('')}<text class="chart-axis" x="${left}" y="226">${dateFr(data[0].date)}</text>${data.length>1?`<text class="chart-axis" x="${right}" y="226" text-anchor="end">${dateFr(data.at(-1).date)}</text>`:''}</svg><p class="chart-detail" id="chartDetail">${data.length===1?'Premier repère enregistré. La courbe se dessinera avec les prochaines séances.':'Sélectionne un point pour voir sa valeur.'}</p>`}
function progressView(){const tabs=`<div class="segmented" style="margin-bottom:24px">${[['overview','Vue d’ensemble'],['history','Historique'],['records','Records'],['tests','Références']].map(([k,label])=>`<button class="seg-btn ${progressMode===k?'active':''}" data-action="progressMode:${k}">${label}</button>`).join('')}</div>`;let content='';if(progressMode==='records'){content=recordsView()}else if(progressMode==='overview'){const names=[...new Set([...state.tests.map(t=>t.ex),...state.history.flatMap(h=>h.sets.map(s=>s.name))])];if(!names.includes(chartExercise)&&names.length)chartExercise=names[0];content=`<div class="grid3">${['Développé couché','Développé militaire','Tractions lestées'].map(n=>{const t=latestTest(n);return `<div class="ref-card"><h3>${n}</h3><div class="ref-value">${t?fmt(e1rm(t)):'—'} <small>kg</small></div><p class="ref-source">e1RM ${n==='Tractions lestées'?'corps + lest':'estimé'}</p></div>`}).join('')}</div><div class="spacer"></div><section class="card chart-card"><div class="row between card-head wrap"><div><h2>De plus en plus fort.</h2><p class="micro muted" style="margin-top:6px">Maximum estimé · Epley · kg</p></div><select aria-label="Exercice du graphique" data-input="chartExercise" style="max-width:235px">${names.map(n=>`<option ${n===chartExercise?'selected':''}>${esc(n)}</option>`).join('')}</select></div>${chartHTML(chartExercise)}</section><div class="section-heading"><h2>Tes dernières séances</h2><button class="link-btn" data-action="showHistory">Tout voir ${icon('up')}</button></div><section class="card">${state.history.length?historyRows(state.history.slice(-3).reverse()):empty('history','Du concret, bientôt ici.','Tes séances enregistrées alimenteront cet historique et tes courbes.')}</section>`}else if(progressMode==='history'){content=`<section class="card"><div class="row between card-head"><h2>${state.history.length} séance${state.history.length>1?'s':''} enregistrée${state.history.length>1?'s':''}</h2><span class="small muted">${fmt(state.history.reduce((n,h)=>n+workload(h.sets),0)/1000)} t</span></div>${state.history.length?historyRows([...state.history].reverse()):empty('calendar','Ton carnet est prêt.','Une fois ta séance terminée, tu retrouveras chaque charge, répétition et série ici.')}<div class="note" style="margin-top:20px">Volume renseigné = charge saisie × répétitions. Le poids du corps n’y est pas ajouté et les haltères ne sont pas doublés automatiquement.</div></section>`}else{content=`<section class="card"><div class="row between card-head"><h2>Références de force</h2>${btn('Ajouter','test:new','primary','plus')}</div>${state.tests.length?[...state.tests].reverse().map(t=>`<article class="test-row"><div class="row between wrap"><div><h3>${esc(t.ex)}</h3><p class="small muted">${fmt(t.load)} kg${t.ex==='Tractions lestées'?' de lest':''} × ${t.reps} · RIR ${t.rir}</p></div><span class="pill orange">e1RM ${fmt(e1rm(t))} kg</span></div><div class="row between" style="margin-top:12px"><span class="micro muted">${dateFr(t.date)}${t.ex==='Tractions lestées'?' · PDC '+fmt(t.bw||state.profile.weight)+' kg':''}</span><div class="actions"><button class="icon-btn" data-action="test:${esc(t.id)}" aria-label="Modifier le test ${esc(t.ex)}">${icon('edit')}</button><button class="icon-btn" data-action="deleteTest:${esc(t.id)}" aria-label="Supprimer le test ${esc(t.ex)}">${icon('trash')}</button></div></div></article>`).join(''):empty('target','Ajoute ton premier repère.','Une charge, un nombre de répétitions et une marge pour calibrer ton cycle.')}</section><div class="spacer"></div><section class="card"><div class="row between card-head"><h2>Charges de travail</h2><button class="link-btn" data-action="working:new">${icon('plus')}Ajouter</button></div><p class="small muted" style="margin-top:8px">Elles restent séparées de tes tests de force.</p>${workingLoadEntries().map(({name,load})=>`<div class="working-row row between"><b>${esc(name)}</b><div class="row"><strong>${fmt(load)} kg</strong><button class="icon-btn" data-action="working:${esc(name)}" aria-label="Modifier la charge ${esc(name)}">${icon('edit')}</button></div></div>`).join('')}</section>`}return intro('Le progrès se mesure.','Tes efforts deviennent des repères.')+tabs+content}
function settingsView(){const coach=activeGeneratedProgram();return intro('Ta façon de t’entraîner.','Les bons réglages, au bon endroit.')+`<div class="settings-grid"><section class="card coach-settings-card"><span class="eyebrow orange">COACH ADAPTATIF</span><h2 class="settings-heading" style="margin-top:8px">${coach?'Ton programme généré est actif.':'Génère ton prochain cycle.'}</h2><p class="small muted">${coach?`${fmt(coach.goalSnapshot?.currentWeightKg)} → ${fmt(coach.goalSnapshot?.targetWeightKg)} kg · ${coach.inputSnapshot?.availability?.daysPerWeek||6} séances/semaine · ${coach.weeks.length} semaines.`:'Poids cible, disponibilités, niveau, rythme de progression et priorités musculaires.'}</p><div class="spacer"></div>${btn(coach?'Modifier mon programme':'Configurer mon programme','coachSetup','primary','target')}</section><section class="card"><h2 class="settings-heading">Ton profil & ton cycle</h2><form id="profileForm"><div class="field-grid"><div class="field"><label for="profileNameInput">Prénom</label><input id="profileNameInput" name="name" value="${esc(state.profile.name)}" required maxlength="50"></div><div class="field"><label for="profileWeight">Poids du corps · kg</label><input id="profileWeight" name="weight" type="number" value="${state.profile.weight}" min="1" max="500" step=".1" required></div><div class="field" style="grid-column:1/-1"><label for="profileWeek">Semaine du cycle</label><select id="profileWeek" name="week">${Array.from({length:21},(_,w)=>`<option value="${w}" ${w===state.profile.week?'selected':''}>Semaine ${w} · ${phase(w).short}</option>`).join('')}</select></div></div><button class="btn btn-primary btn-wide" type="submit" style="margin-top:22px">${icon('check')}Enregistrer les réglages</button></form><div class="note" style="margin-top:20px">Le cycle avance quand tu le décides. Une nouvelle semaine ne s’active pas automatiquement.</div></section><section class="card"><h2 class="settings-heading">Pendant la séance</h2>${[['autoRest','Repos automatique','Après une série, ou après la paire en superset.'],['sound','Signal sonore','Un signal discret à la fin du repos, si l’app est ouverte.'],['motion','Animations','Transitions et retours visuels pendant tes actions.']].map(([key,title,desc])=>`<div class="toggle-row"><div><b>${title}</b><p>${desc}</p></div><button class="switch" role="switch" aria-checked="${state.preferences[key]}" aria-label="${title}" data-action="toggle:${key}"></button></div>`).join('')}<div class="note" style="margin-top:20px">Le chronomètre se recale au retour dans l’app. Le son dépend des autorisations du navigateur.</div></section><section class="card"><h2 class="settings-heading">Tes données, avec toi.</h2><p class="small muted">La sauvegarde reste dans ce navigateur. Pour changer d’appareil ou de fichier, exporte puis importe ton carnet.</p><div class="row wrap" style="margin-top:21px">${btn('Exporter','export','outline','download')}${btn('Importer','import','outline','upload')}</div><p class="micro muted" style="margin-top:17px">Muscu Coach Pro · 3.3 · Bibliothèque d’exercices unifiée · Compatible avec les sauvegardes V2 et V3.</p>${state.savedAt?`<p class="micro muted" style="margin-top:6px">Dernière sauvegarde : ${new Date(state.savedAt).toLocaleString('fr-FR')}</p>`:''}</section><section class="card"><h2 class="settings-heading">Comprendre tes repères</h2><p class="small muted">RIR, e1RM, back-off et progression : les termes du programme, expliqués simplement.</p><div class="spacer"></div>${btn('Le guide rapide','help','outline','info')}<div class="divider"></div><button class="link-btn" style="color:#ed9999" data-action="reset">Réinitialiser toutes les données</button></section></div>`}
let modalActions={},modalReturnFocus=null;
function showModal(title,content,actions=[],wide=false){modalReturnFocus=document.activeElement;modalActions={};$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="modal-head"><h2 id="dialogTitle">${esc(title)}</h2><button class="icon-btn" data-action="closeModal" aria-label="Fermer">${icon('close')}</button></div>${content}${actions.length?`<div class="modal-actions">${actions.map((a,i)=>{modalActions['m'+i]=a.fn;return `<button class="btn btn-${a.kind||'primary'}" data-modal-action="m${i}">${a.label}</button>`}).join('')}</div>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input,.modal select,.modal button')?.focus());}
function closeModal(){$('#modalRoot').innerHTML='';document.body.style.overflow='';modalActions={};if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function confirmDialog(title,message,fn,label='Confirmer'){showModal(title,`<p class="small muted">${message}</p>`,[{label:'Annuler',kind:'outline',fn:closeModal},{label,fn:()=>{closeModal();fn()}}]);}
function loadConventionForCoach(name){const item=exerciseLibraryItems().find(x=>x.exerciseId===exerciseStableId(name)||normalizedExerciseName(x.name)===normalizedExerciseName(name)),eq=String(item?.equipment||'');if(/Tractions/i.test(name))return 'added_to_bodyweight';if(/haltère/i.test(name)||/Haltère/i.test(eq))return 'per_hand';if(/Machine|Poulie|Smith/i.test(eq))return 'machine_stack';return 'total_external'}
function coachPerformanceReferences(){return state.tests.map(t=>({id:String(t.id),exerciseId:t.exerciseId||exerciseStableId(t.ex),loadConvention:loadConventionForCoach(t.ex),loadKg:Number(t.load)||0,reps:Math.max(1,Math.round(Number(t.reps)||1)),rir:Math.max(0,Math.min(5,Number(t.rir)||0)),date:t.date||null})).filter(x=>x.exerciseId&&Number.isFinite(x.loadKg))}
function coachPriorityOptions(selected=''){const names=['','Pectoraux','Dos','Épaules','Biceps','Triceps','Quadriceps','Ischios','Fessiers','Mollets'];return names.map(x=>`<option value="${x}" ${x===selected?'selected':''}>${x||'Aucune'}</option>`).join('')}
function coachSetupModal(){const active=activeGeneratedProgram(),last=state.coaching?.lastGenerationInput||active?.inputSnapshot||{},g=last.goal||{},a=last.availability||{},tp=last.trainingProfile||{},c=last.constraints||{},u=last.user||{},prior=g.musclePriorities||[],days=Number(a.daysPerWeek)||6,weekdays=Array.isArray(a.weekdays)&&a.weekdays.length?a.weekdays:(days===6?[1,2,3,4,5,6]:days===5?[1,2,3,5,6]:days===4?[1,2,4,5]:[1,3,5]),current=Number(g.currentWeightKg)||Number(state.profile.weight)||70,target=Number(g.targetWeightKg)||Math.round((current+10)*10)/10;showModal(active?'Modifier ton programme Coach.':'Créer ton programme Coach.',`<form id="coachSetupForm" class="coach-form"><section class="coach-form-section"><span class="eyebrow orange">01 · OBJECTIF</span><div class="field-grid"><div class="field"><label>Poids actuel · kg</label><input name="currentWeight" type="number" min="30" max="300" step="0.1" required value="${current}"></div><div class="field"><label>Poids cible · kg</label><input name="targetWeight" type="number" min="30" max="350" step="0.1" required value="${target}"></div><div class="field"><label>Rythme de prise de masse</label><select name="gainPace">${[['controlled','Contrôlé'],['normal','Normal'],['aggressive','Agressif']].map(([v,l])=>`<option value="${v}" ${(g.gainPace?.preset||'normal')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Date cible · facultatif</label><input name="targetDate" type="date" value="${g.targetDate||''}"></div></div></section><section class="coach-form-section"><span class="eyebrow orange">02 · TON PROFIL</span><div class="field-grid"><div class="field"><label>Âge</label><input name="age" type="number" min="16" max="90" step="1" value="${u.age||''}" placeholder="32"></div><div class="field"><label>Taille · cm</label><input name="height" type="number" min="130" max="230" step="1" value="${u.heightCm||''}" placeholder="183"></div><div class="field"><label>Expérience</label><select name="experience">${[['beginner','Débutant'],['novice','Reprise / novice'],['intermediate','Intermédiaire'],['advanced','Avancé']].map(([v,l])=>`<option value="${v}" ${(tp.experienceLevel||'novice')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>État / contraintes</label><select name="healthStatus"><option value="ok" ${(c.healthStatus||'ok')==='ok'?'selected':''}>Aucune contrainte particulière</option><option value="managed" ${c.healthStatus==='managed'?'selected':''}>Contrainte gérée / suivie</option><option value="needs_clearance" ${c.healthStatus==='needs_clearance'?'selected':''}>Feu vert nécessaire avant entraînement</option></select></div><div class="field" style="grid-column:1/-1"><label>Contraintes ou blessures · facultatif</label><textarea name="issues" rows="2" maxlength="500" placeholder="Ex : cheville en rééducation, éviter les impacts…">${esc((c.reportedIssues||[]).join(', '))}</textarea></div></div></section><section class="coach-form-section"><span class="eyebrow orange">03 · DISPONIBILITÉS</span><div class="field-grid"><div class="field"><label>Séances / semaine</label><select name="daysPerWeek">${[3,4,5,6].map(v=>`<option value="${v}" ${days===v?'selected':''}>${v} séances</option>`).join('')}</select></div><div class="field"><label>Durée max / séance</label><select name="maxMinutes">${[60,75,90,105,120].map(v=>`<option value="${v}" ${(Number(a.maxSessionMinutes)||75)===v?'selected':''}>${v} min</option>`).join('')}</select></div><div class="field" style="grid-column:1/-1"><label>Jours disponibles · choisis exactement le même nombre</label><div class="coach-weekdays">${WEEKDAYS.map((name,i)=>`<label class="coach-day"><input type="checkbox" name="weekday" value="${i+1}" ${weekdays.includes(i+1)?'checked':''}><span>${name.slice(0,3)}</span></label>`).join('')}</div></div><div class="field"><label>Durée du cycle</label><select name="horizon">${[12,16,20].map(v=>`<option value="${v}" ${(Number(last.planning?.requestedHorizonWeeks)||20)===v?'selected':''}>${v} semaines</option>`).join('')}</select></div><div class="field"><label>Début du cycle</label><input name="startDate" type="date" required value="${a.startDate||localDate()}"></div></div></section><section class="coach-form-section"><span class="eyebrow orange">04 · PRIORITÉS MUSCULAIRES</span><div class="field-grid"><div class="field"><label>Priorité n°1 · forte</label><select name="priority1">${coachPriorityOptions(prior[0]?.muscle||'')}</select></div><div class="field"><label>Priorité n°2 · moyenne</label><select name="priority2">${coachPriorityOptions(prior[1]?.muscle||'')}</select></div><div class="field"><label>Priorité n°3 · secondaire</label><select name="priority3">${coachPriorityOptions(prior[2]?.muscle||'')}</select></div></div><div class="note">Le moteur utilise ta bibliothèque actuelle et conserve l’identité exacte de chaque exercice. Une autre machine ou variante ne récupère pas automatiquement la même calibration.</div></section><button type="submit" class="btn btn-primary btn-wide">Générer mon programme ${icon('arrow')}</button></form>`,[],true)}
function coachInputFromForm(form){const f=new FormData(form),days=Number(f.get('daysPerWeek')),weekdays=[...form.querySelectorAll('input[name="weekday"]:checked')].map(x=>Number(x.value)).sort((a,b)=>a-b);if(weekdays.length!==days)throw Error(`Choisis exactement ${days} jours d’entraînement.`);const priorities=[['priority1',1,5],['priority2',2,4],['priority3',3,3]].map(([key,rank,importance])=>({muscle:String(f.get(key)||''),rank,importance})).filter(x=>x.muscle);if(new Set(priorities.map(x=>x.muscle)).size!==priorities.length)throw Error('Choisis des priorités musculaires différentes.');const currentWeightKg=Number(f.get('currentWeight')),targetWeightKg=Number(f.get('targetWeight')),issues=String(f.get('issues')||'').split(',').map(x=>x.trim()).filter(Boolean),active=activeGeneratedProgram();return {schemaVersion:'1.0.0',request:{id:uid(),requestedAt:new Date().toISOString()},user:{age:Number(f.get('age'))||null,heightCm:Number(f.get('height'))||null,weightKg:currentWeightKg},trainingProfile:{experienceLevel:String(f.get('experience')),experienceMonths:0,consistency:'returning',weeksSinceLast:0,equipmentProfile:'full_gym'},goal:{type:'mass_gain',currentWeightKg,targetWeightKg,targetDate:String(f.get('targetDate')||'')||null,gainPace:String(f.get('gainPace')),musclePriorities:priorities},availability:{daysPerWeek:days,weekdays,maxSessionMinutes:Number(f.get('maxMinutes')),startDate:String(f.get('startDate')),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Paris'},constraints:{healthStatus:String(f.get('healthStatus')),reportedIssues:issues,excludedExerciseIds:[],excludedMovementTags:[]},otherActivities:[],performanceReferences:coachPerformanceReferences(),trainingHistory:state.history.slice(-12).map(h=>({id:h.id,date:h.date,name:h.name,week:h.week})),planning:{requestedHorizonWeeks:Number(f.get('horizon')),allowStrengthBlocks:true,existingProgramId:active?.id||null}}}
function coachPreviewModal(program,input){const warnings=program.warnings||[],first=program.weeks?.[0],pace=program.goalSnapshot?.gainPace?.targetBodyweightPctPerWeek;pendingCoachProgram={program,input};showModal('Ton programme est prêt.',`<div class="coach-preview"><div class="coach-preview-hero"><span class="eyebrow orange">PRISE DE MASSE · ${program.weeks.length} SEMAINES</span><h3>${fmt(program.goalSnapshot.currentWeightKg)} → ${fmt(program.goalSnapshot.targetWeightKg)} kg</h3><p>${input.availability.daysPerWeek} séances/semaine · cible ${fmt(pace,2)} % du poids/semaine.</p></div>${warnings.length?`<div class="coach-warning">${icon('info')}<div><b>${warnings.length} point${warnings.length>1?'s':''} à surveiller</b>${warnings.map(w=>`<p>${esc(w.message)}</p>`).join('')}</div></div>`:''}<div class="coach-preview-blocks">${program.blocks.map(b=>`<div><b>${esc(b.label)}</b><span>S${b.startWeek}${b.endWeek!==b.startWeek?'–'+b.endWeek:''}</span></div>`).join('')}</div><h3 class="coach-preview-title">Première semaine</h3><div class="coach-preview-sessions">${(first?.sessions||[]).map(s=>`<div><span>${WEEKDAYS[s.dayOfWeek-1]}</span><b>${esc(s.name)}</b><small>${s.exercises.length} exercices · ${s.exercises.reduce((n,e)=>n+e.sets,0)} séries</small></div>`).join('')}</div><div class="note">Activer ce programme remplace le planning futur affiché, mais ne supprime ni ton historique, ni tes charges de travail, ni tes tests de force.</div></div>`,[{label:'Modifier mes paramètres',kind:'outline',fn:coachSetupModal},{label:'Activer ce programme',fn:activatePendingCoachProgram}],true)}
function handleCoachSetupSubmit(form){let input;try{input=coachInputFromForm(form)}catch(err){toast(err.message);return}const result=generateMassGainProgram(input,{persist:false});if(result?.status!=='generated'){const errors=result?.errors||[];showModal('Impossible de générer le programme.',`<div class="stack">${errors.map(e=>`<div class="note"><b>${esc(e.message)}</b></div>`).join('')||'<div class="note">Vérifie les paramètres renseignés.</div>'}</div>`,[{label:'Retour',fn:coachSetupModal}]);return}coachPreviewModal(result,input)}
function activatePendingCoachProgram(){if(!pendingCoachProgram)return;if(state.draft){toast('Termine ou abandonne d’abord la séance en cours.');return}const {program,input}=pendingCoachProgram,previous=activeGeneratedProgram();if(previous?.id===program.id)program.revision=Math.max(1,Number(previous.revision||1)+1);window.MuscuCoachStorage.saveProgramInNotebook(state,program,{activate:true,input});state.profile={...state.profile,weight:input.goal.currentWeightKg,week:1,goal:'Prise de masse',experience:input.trainingProfile.experienceLevel};state.planOverrides={};state.dayOverrides={};previewWeek=1;programMode='sessions';if(!save()){toast('Programme généré, mais la sauvegarde locale a échoué.');return}queueCoachRemote(window.MuscuCoachStorage.saveProgramRemote(program),'Programme Supabase non synchronisé');pendingCoachProgram=null;closeModal();navigate('program');toast('Programme Coach activé et synchronisation lancée.');}
function startWorkout(day,w=state.profile.week){if(state.draft){showModal('Une séance est déjà en cours.',`<p class="muted small">${esc(program[state.draft.templateDay].name)} · ${draftStats().done} séries validées. Tu peux la reprendre ou l’abandonner pour en commencer une autre.</p>`,[{label:'Reprendre',fn:()=>{closeModal();navigate('workout')}},{label:'Abandonner & changer',kind:'danger',fn:()=>{state.draft=null;save();closeModal();startWorkout(day,w)}}]);return}
if(w!==state.profile.week){confirmDialog('Utiliser la semaine '+w+' ?',`Le cycle passera en ${esc(phase(w).name.toLowerCase())}. Tes séries seront calculées pour cette semaine.`,()=>beginWorkout(day,w),'Démarrer la séance');return}beginWorkout(day,w)}
function beginWorkout(day,w){const meta=sessionMetaForDay(day,w);if(!meta){toast('Aucune séance programmée ce jour.');return}state.profile.week=w;selectedDay=day;state.draft={id:uid(),day,templateDay:Number.isInteger(meta.templateDay)?meta.templateDay:(day<6?day:0),sessionName:meta.name,sessionFocus:meta.focus,generatedSessionId:meta.sessionId||null,coachProgramId:activeGeneratedProgram()?.id||null,week:w,bodyWeight:state.profile.weight,started:Date.now(),index:0,rest:null,exercises:planFor(day,w).map(e=>({...e,sets:e.sets.map(s=>({...s,load:s.load??0,done:false}))}))};save();navigate('workout');requestWakeLock();}
async function requestWakeLock(){try{if(navigator.wakeLock&&document.visibilityState==='visible'&&state.draft&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen');if(wakeLock)wakeLock.addEventListener('release',()=>wakeLock=null)}catch{}}
function releaseWake(){try{wakeLock?.release()}catch{}wakeLock=null}
function setExercise(index){if(!state.draft)return;state.draft.index=clamp(index,0,state.draft.exercises.length-1);save();render();}
function toggleSet(index){const d=state.draft,e=d?.exercises[d.index],s=e?.sets[index];if(!s)return;if(s.done){s.done=false;d.rest=null;save();render();return}const row=$(`[data-setrow="${index}"]`),inputs=[...row.querySelectorAll('input')];if(inputs.some(x=>x.value.trim()==='')){toast('Renseigne la charge, les répétitions et le RIR.');return}const vals=Object.fromEntries(inputs.map(i=>[i.dataset.field,Number(i.value)]));if(!Number.isFinite(vals.load)||vals.load<0||vals.load>2000||!Number.isInteger(vals.reps)||vals.reps<1||vals.reps>100||!Number.isFinite(vals.rir)||vals.rir<0||vals.rir>5){toast('Vérifie la charge, les reps et le RIR de 0 à 5.');return}if(vals.load===0&&!e.allowZero&&!/Tractions|dips/i.test(e.name)){toast('Règle ta charge avant de valider cette série.');return}Object.assign(s,vals,{done:true});let doRest=true;if(e.tag.startsWith('superset')){const peer=d.exercises.findIndex((x,i)=>i!==d.index&&x.tag===e.tag);if(peer>=0&&d.exercises[peer].sets[index]&&!d.exercises[peer].sets[index].done){d.index=peer;doRest=false;toast('Superset : enchaîne avec '+d.exercises[peer].name+'.')}else if(peer>=0&&d.exercises[peer].sets.some(x=>!x.done)){d.index=Math.min(d.index,peer)}}if(doRest&&state.preferences.autoRest)d.rest=nextRest(d,e);save();render();if(e.sets.every(x=>x.done)&&!e.tag.startsWith('superset'))toast('Exercice complété. Bien joué !');}
function exerciseRestDuration(e){const n=Number(state.preferences.exerciseRest);return Number.isFinite(n)&&n>=15&&n<=900?n:Math.min(900,e.rest+60)}
function nextRest(d,e){
 if(d.exercises.every(x=>x.sets.every(s=>s.done)))return null;
 const group=e.tag.startsWith('superset')?d.exercises.filter(x=>x.tag===e.tag):[e];
 const between=group.every(x=>x.sets.every(s=>s.done));
 const seconds=between?exerciseRestDuration(e):e.rest;
 return {end:Date.now()+seconds*1000,total:seconds,paused:null,kind:between?'exercise':'set'};
}
function startRest(seconds){if(!state.draft)return;const d=state.draft;if(seconds!=null)d.rest={end:Date.now()+seconds*1000,total:seconds,paused:null,kind:'set'};else d.rest=nextRest(d,d.exercises[d.index]);save();renderTimer();}

function restSeconds(){const r=state.draft?.rest;return r?Math.max(0,r.paused??Math.ceil((r.end-Date.now())/1000)):0}
function renderTimer(){const r=state.draft?.rest;document.body.classList.toggle('timer-running',!!r);if(!r){$('#timerDock').innerHTML='';return}const left=restSeconds();$('#timerDock').innerHTML=`<div class="timer-dock" role="region" aria-label="Chronomètre de repos"><div class="timer-circle"><svg viewBox="0 0 48 48" aria-hidden="true"><circle class="ring-track" cx="24" cy="24" r="21"/><circle id="restRing" class="ring-progress" cx="24" cy="24" r="21" stroke-dasharray="132" stroke-dashoffset="${132*(1-left/r.total)}"/></svg>${icon('timer')}</div><div><div class="timer-caption">${r.paused!=null?'REPOS EN PAUSE':r.kind==='exercise'?'REPOS ENTRE EXERCICES':'REPOS ENTRE SÉRIES'}</div><div class="timer-value" id="restValue" role="timer" aria-live="off">${timeStr(left)}</div></div><div class="timer-controls"><button data-action="restAdd" aria-label="Ajouter 30 secondes">+30 s</button><button data-action="restPause" aria-label="${r.paused!=null?'Reprendre':'Mettre en pause'} le repos">${icon(r.paused!=null?'play':'pause')}</button><button data-action="restSkip">Passer</button></div></div>`}
function tick(){syncCalendar(true);const d=state.draft;if(!d)return;if($('#elapsed'))$('#elapsed').textContent=timeStr((Date.now()-d.started)/1000);const r=d.rest;if(!r)return;const left=restSeconds();if(left<=0&&r.paused==null){d.rest=null;save();renderTimer();toast('Repos terminé. À toi de jouer !');beep();return}if($('#restValue'))$('#restValue').textContent=timeStr(left);$('#restRing')?.setAttribute('stroke-dashoffset',String(132*(1-left/r.total)));}
function beep(){if(!state.preferences.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.setValueAtTime(750,audioCtx.currentTime);g.gain.setValueAtTime(.07,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.35);o.start();o.stop(audioCtx.currentTime+.35)}catch{}}
function nextSuggestion(ex){const sets=ex.sets.filter(s=>s.done),inc=increment(ex.name);if(!sets.length)return null;const exerciseId=exerciseKey(ex),current=sets[0].load;if(sets.length<ex.sets.length)return{exerciseId,name:canonicalExerciseName(ex.name),load:current,reason:'Séance partielle · charge conservée',change:0};if(ex.manual){return{exerciseId,name:canonicalExerciseName(ex.name),load:current,reason:'Séance adaptée · charge conservée',change:0}}if(ex.method.includes('back-off')||/Force|Calibration|Recalibration|Volume allégé/.test(ex.method))return{exerciseId,name:canonicalExerciseName(ex.name),load:current,reason:'Charge à suivre selon le bloc du cycle',change:0};if(sets.every(s=>s.reps>=s.max&&s.rir>=1))return{exerciseId,name:canonicalExerciseName(ex.name),load:round(current+inc,inc),reason:'Haut de fourchette atteint avec de la marge',change:inc};if(sets.some(s=>s.reps<s.min||s.rir===0))return{exerciseId,name:canonicalExerciseName(ex.name),load:Math.max(0,round(current-inc,inc)),reason:'Marge faible · proposition à ajuster',change:-inc};return{exerciseId,name:canonicalExerciseName(ex.name),load:current,reason:'Continue à progresser dans la fourchette',change:0}}
function celebrate(){if(!state.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='confetti';el.innerHTML=Array.from({length:28},()=>`<i style="--x:${Math.round(Math.random()*600-300)}px;--y:${Math.round(Math.random()*600-200)}px;--rot:${Math.round(Math.random()*720)}deg;animation-delay:${Math.random()*.2}s"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),1500);}
function exerciseNameForId(id){const item=exerciseLibraryItems().find(x=>x.exerciseId===id);if(item)return item.name;for(const name of Object.keys(state.workLoads||{}))if(exerciseStableId(name)===id)return canonicalExerciseName(name);for(const t of state.tests||[])if((t.exerciseId||exerciseStableId(t.ex))===id)return canonicalExerciseName(t.ex);for(const h of state.history||[])for(const set of h.sets||[])if((set.exerciseId||exerciseStableId(set.name))===id)return canonicalExerciseName(set.name);return id.replace(/^exercise:/,'').replace(/^custom:/,'').replace(/_/g,' ')}
function workingLoadEntries(){const map=new Map();for(const [id,load] of Object.entries(state.workLoadsByExerciseId||{}))map.set(id,{exerciseId:id,name:exerciseNameForId(id),load});for(const [name,load] of Object.entries(state.workLoads||{})){const id=exerciseStableId(name);if(!map.has(id))map.set(id,{exerciseId:id,name:canonicalExerciseName(name),load})}return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr'))}
function testModal(id){const current=state.tests.find(t=>t.id===id),t=current||{ex:'Développé couché',exerciseId:exerciseStableId('Développé couché'),load:'',reps:'',rir:1,bw:state.profile.weight,date:localDate()};showModal(current?'Ajuster ton repère.':'Un nouveau repère.',`<form id="testForm" data-id="${current?esc(id):''}"><div class="field-grid"><div class="field" style="grid-column:1/-1"><label for="testEx">Exercice</label><select id="testEx" name="ex" required>${exerciseSelectOptions(t.ex)}</select><p class="micro muted" style="margin-top:7px">Même bibliothèque que dans Programme et pendant les séances.</p></div><div class="field"><label for="testLoad">Charge / lest · kg</label><input id="testLoad" name="load" type="number" step=".25" min="0" max="2000" value="${t.load}" required></div><div class="field"><label for="testReps">Répétitions</label><input id="testReps" name="reps" type="number" step="1" min="1" max="100" value="${t.reps}" required></div><div class="field"><label for="testRir">RIR · reps en réserve</label><input id="testRir" name="rir" type="number" step=".5" min="0" max="5" value="${t.rir}" required></div><div class="field"><label for="testDate">Date</label><input id="testDate" name="date" type="date" value="${t.date||localDate()}" required></div><div class="field" style="grid-column:1/-1"><label for="testBw">Poids du corps · kg (tractions lestées)</label><input id="testBw" name="bw" type="number" min="1" max="500" step=".1" value="${t.bw||state.profile.weight}" required></div></div><div class="note">${icon('info')}La référence est liée à l’identifiant unique de l’exercice de la bibliothèque. Un renommage ou un ancien alias ne crée plus un second mouvement.</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:23px">${icon('check')}Enregistrer la référence</button></form>`)}
function workingModal(name){const isNew=!name||name==='new',canonical=canonicalExerciseName(isNew?'':name),id=canonical?exerciseStableId(canonical):'',entry=id?workingLoadEntries().find(x=>x.exerciseId===id):null;showModal('Régler une charge de travail.',`<form id="workingForm"><div class="field"><label for="workingEx">Exercice</label><select id="workingEx" name="ex" required>${exerciseSelectOptions(canonical)}</select><p class="micro muted" style="margin-top:7px">La charge sera réutilisée automatiquement partout où ce même exercice apparaît.</p></div><div class="spacer"></div><label for="workingLoad">Charge de travail · kg</label><input id="workingLoad" name="load" type="number" step=".25" min="0" max="2000" value="${entry?entry.load:''}" required><button type="submit" class="btn btn-primary btn-wide" style="margin-top:23px">Enregistrer la charge</button></form>`)}
function helpModal(){showModal('Les bons repères.',`<div class="stack"><div><h3 style="font-size:16px">RIR : ce qu’il reste dans le moteur.</h3><p class="small muted" style="margin-top:8px">Un RIR de 2 signifie que tu estimes pouvoir faire encore 2 répétitions propres. Un RIR de 0 signifie aucune répétition en réserve.</p></div><div><h3 style="font-size:16px">e1RM : une estimation, pas une charge à tenter.</h3><p class="small muted" style="margin-top:8px">Calcul Epley : charge × (1 + reps / 30), sans ajouter le RIR. Il sert de repère pour comparer tes efforts. Pour les tractions, le résultat comprend le poids du corps.</p></div><div><h3 style="font-size:16px">Superset : deux exercices enchaînés.</h3><p class="small muted" style="margin-top:8px">Après la première série, l’app te propose l’exercice associé. Le repos démarre une fois la paire terminée.</p></div><div><h3 style="font-size:16px">Top set & back-off.</h3><p class="small muted" style="margin-top:8px">Une première série plus lourde, puis des séries avec une charge allégée. Les charges et objectifs sont indiqués séparément.</p></div><div><h3 style="font-size:16px">La progression des charges.</h3><p class="small muted" style="margin-top:8px">Une hausse est proposée si toutes les séries atteignent le haut de la fourchette avec au moins 1 rep en réserve. La charge proposée est ensuite réutilisée automatiquement partout où le même exercice de la bibliothèque réapparaît. Une séance partielle conserve la charge. Le bloc force recalcule ses objectifs depuis tes tests.</p></div></div>`,[{label:'Compris',fn:closeModal}]);}
function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='muscu-coach-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde exportée.');}
async function importData(file){if(!file)return;try{if(file.size>5000000)throw Error('too large');const imported=normalise(JSON.parse(await file.text()));confirmDialog('Importer ce carnet ?',`${imported.tests.length} référence${imported.tests.length>1?'s':''} et ${imported.history.length} séance${imported.history.length>1?'s':''} seront chargées. Tes données actuelles seront remplacées. Tu peux les exporter avant d’importer.`,()=>{state=imported;save();render();toast('Carnet importé avec succès.');},'Importer')}catch{toast('Fichier invalide. Choisis une sauvegarde Muscu Coach V2 ou V3.')}$('#backupInput').value=''}
function chooseWeek(w){confirmDialog('Passer en semaine '+w+' ?',phase(w).desc,()=>{state.profile.week=w;previewWeek=w||1;save();render();toast('Semaine du cycle mise à jour.')},'Choisir cette semaine')}
function action(value){const split=value.indexOf(':'),cmd=split<0?value:value.slice(0,split),arg=split<0?'':value.slice(split+1);switch(cmd){
case 'today':selectionMode='auto';selectedDay=todayPlanDay();render();break;case 'coachSetup':coachSetupModal();break;case 'chooseSession':navigate('workout');break;case 'adapt':adaptModal();break;case 'exerciseLibrary':exerciseLibraryModal();break;case 'libraryAdd':exerciseLibraryEditor();break;case 'libraryEdit':exerciseLibraryEditor(arg);break;case 'libraryDelete':deleteCustomExercise(arg);break;case 'editPlan':planEditorModal(+arg,previewWeek);break;case 'editCurrentPlan':planEditorModal(+arg,state.profile.week);break;case 'planAdd':planExerciseEditor(-1);break;case 'planEdit':planExerciseEditor(+arg);break;case 'planMove':{const [i,delta]=arg.split(',').map(Number);movePlannedExercise(i,delta);break}case 'planRemove':removePlannedExercise(+arg);break;case 'planReset':{const [w,d]=arg.split(',').map(Number);confirmDialog('Réinitialiser cette séance ?','Tes personnalisations de cette séance seront supprimées. L’historique déjà enregistré ne change pas.',()=>{resetPlanOverride(w,d);planEditorModal(d,w)},'Réinitialiser');break}case 'addExercise':exerciseEditor(-1);break;case 'swapExercise':exerciseEditor(+arg);break;case 'removeExercise':removeExercise(+arg);break;case 'addSet':changeSetCount(1);break;case 'removeSet':changeSetCount(-1);break;case 'exerciseMemory':exerciseHistoryModal(arg||state.draft.exercises[state.draft.index].name);break;case 'exerciseNote':exerciseNoteModal(arg||state.draft.exercises[state.draft.index].name);break;case 'showRecords':progressMode='records';navigate('progress');break;case 'closeModal':closeModal();break;case 'help':helpModal();break;
case 'showRefs':progressMode='tests';navigate('progress');break;case 'showHistory':progressMode='history';navigate('progress');break;case 'showCycle':programMode='cycle';navigate('program');break;
case 'selectDay':selectedDay=+arg;selectionMode='manual';render();break;case 'restInfo':showRestDay(+arg);break;
case 'programMode':programMode=arg;render();break;case 'preview':previewWeek=+arg;programMode='sessions';render();break;case 'setWeek':chooseWeek(+arg);break;
case 'organizeWeek':organizeWeekModal(previewWeek);break;case 'resetWeek':resetWeekDays(+arg);closeModal();break;case 'showRecap':showSessionRecap(arg);break;case 'repeatResult':repeatResult(arg);break;
case 'start':startWorkout(+arg);break;case 'startPreview':startWorkout(+arg,previewWeek);break;case 'resume':navigate('workout');requestWakeLock();break;
case 'exercise':setExercise(+arg);break;case 'check':toggleSet(+arg);break;case 'finish':finishWorkout();break;
case 'discard':confirmDialog('Abandonner cette séance ?','Les séries de cette séance ne seront pas ajoutées à l’historique.',()=>{state.draft=null;save();releaseWake();navigate('home')},'Abandonner');break;
case 'copyLoad':{const e=state.draft.exercises[state.draft.index];const first=e.sets[0].load;if(first===0&&!/Tractions|dips/i.test(e.name)){toast('Renseigne d’abord la première charge.');break}e.sets.forEach(s=>{if(!s.done)s.load=first});save();render();toast('Charge copiée sur les séries restantes.');break}
case 'exerciseInfo':{const e=state.draft.exercises[state.draft.index];showModal(e.name,`<div class="stack"><div class="note"><b>${esc(e.method)}</b><br>${e.sets.map((s,i)=>'Série '+(i+1)+' : '+s.min+'–'+s.max+' reps · RIR '+s.rir+(s.label!=='Travail'?' · '+s.label:'')).join('<br>')}</div><p class="small muted">Tempo : ${e.tempo}. Dans l’ordre : descente, pause basse, montée, pause haute. X désigne une intention de montée rapide et contrôlée.</p><p class="small muted">Les charges proposées restent ajustables. Les charges des haltères correspondent à un haltère, et celles des tractions au lest ajouté.</p></div>`,[{label:'Retour à ma séance',fn:closeModal}]);break}
case 'restStart':startRest();break;case 'restSkip':if(state.draft){state.draft.rest=null;save();renderTimer()}break;
case 'restAdd':{const r=state.draft?.rest;if(r){r.total+=30;if(r.paused!=null)r.paused+=30;else r.end+=30000;save();renderTimer()}break}
case 'restPause':{const r=state.draft?.rest;if(r){if(r.paused!=null){r.end=Date.now()+r.paused*1000;r.paused=null}else r.paused=restSeconds();save();renderTimer()}break}
case 'restSettings':{const e=state.draft.exercises[state.draft.index];showModal('Ton temps de repos.',`<label for="restInput">Secondes entre les séries</label><input id="restInput" type="number" min="15" max="900" step="15" value="${e.rest}"><label for="exerciseRestInput">Secondes entre les exercices</label><input id="exerciseRestInput" type="number" min="15" max="900" step="15" value="${exerciseRestDuration(e)}"><div class="note">Entre exercices : une minute de plus par défaut. Ton réglage est conservé pour les prochaines séances. Pour un superset, le repos long commence après toutes les séries des deux mouvements. Aucun repos automatique après la dernière série de la séance.</div>`,[{label:'Enregistrer',fn:()=>{const n=+$('#restInput').value;if(!Number.isFinite(n)||n<15||n>900){toast('Choisis entre 15 et 900 secondes.');return}const between=+$('#exerciseRestInput').value;if(!Number.isFinite(between)||between<15||between>900){toast('Choisis entre 15 et 900 secondes entre exercices.');return}e.rest=Math.round(n);state.preferences.exerciseRest=Math.round(between);save();closeModal();render()}}]);break}
case 'progressMode':progressMode=arg;render();break;case 'chartPoint':{const p=progressPoints(chartExercise)[+arg];if(p&&$('#chartDetail'))$('#chartDetail').textContent=`${p.type} · ${dateFr(p.date)} · e1RM ${fmt(p.value)} kg`;break}
case 'test':testModal(arg);break;case 'deleteTest':confirmDialog('Supprimer cette référence ?','Les charges calculées utiliseront tes autres références disponibles.',()=>{state.tests=state.tests.filter(t=>t.id!==arg);save();render();toast('Référence supprimée.')},'Supprimer');break;
case 'working':workingModal(arg);break;case 'deleteHistory':confirmDialog('Supprimer cette séance ?','Les séries seront retirées de l’historique et des graphiques. Tes charges de travail actuelles seront conservées.',()=>{state.history=state.history.filter(h=>h.id!==arg);save();render()},'Supprimer');break;
case 'toggle':state.preferences[arg]=!state.preferences[arg];save();if(arg==='sound'&&state.preferences.sound)beep();render();break;
case 'export':exportData();break;case 'import':$('#backupInput').click();break;
case 'reset':confirmDialog('Repartir de zéro ?','Ton historique, tes réglages et tes références personnalisées seront effacés de cette version. Exporte un carnet si tu veux les conserver.',()=>{state=clone(BASELINE);save();releaseWake();closeModal();navigate('home')},'Réinitialiser');break;
}}
document.addEventListener('click',ev=>{const modalBtn=ev.target.closest('[data-modal-action]');if(modalBtn){modalActions[modalBtn.dataset.modalAction]?.();return}const actionBtn=ev.target.closest('[data-action]');if(actionBtn){action(actionBtn.dataset.action);return}const nav=ev.target.closest('[data-tab]');if(nav){navigate(nav.dataset.tab);return}const brand=ev.target.closest('a[href="#home"]');if(brand){ev.preventDefault();navigate('home')}if(ev.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('.modal')){closeModal();return}if(ev.target.matches('.chart-point')&&['Enter',' '].includes(ev.key)){ev.preventDefault();action(ev.target.dataset.action)}if(ev.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);if(ev.shiftKey&&document.activeElement===items[0]){ev.preventDefault();items.at(-1).focus()}else if(!ev.shiftKey&&document.activeElement===items.at(-1)){ev.preventDefault();items[0].focus()}}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('[data-set][data-field]')&&state.draft){const s=state.draft.exercises[state.draft.index].sets[+el.dataset.set],val=Number(el.value);if(el.value!==''&&Number.isFinite(val)&&val>=0&&val<=(el.dataset.field==='load'?2000:el.dataset.field==='reps'?100:5)){s[el.dataset.field]=val;save()}}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.input==='chooseDay'){selectedDay=+el.value;selectionMode='manual';render()}if(el.dataset.input==='chartExercise'){chartExercise=el.value;render()}if(el.dataset.input==='assignDay'){setDayAssignment(previewWeek,+el.dataset.day,el.value==='rest'?'rest':+el.value)}if(el.id==='backupInput')importData(el.files[0]);});
document.addEventListener('submit',ev=>{const form=ev.target;ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);if(form.id==='coachSetupForm'){handleCoachSetupSubmit(form);return}if(form.id==='exerciseEditForm'){saveExerciseEdit(form,f);return}if(form.id==='planExerciseEditForm'){savePlanExerciseEdit(form,f);return}if(form.id==='exerciseLibraryForm'){saveExerciseLibraryItem(form,f);return}if(form.id==='exerciseNoteForm'){saveExerciseNote(form,f);return}if(form.id==='profileForm'){state.profile={...state.profile,name:String(f.get('name')).trim()||'Joris',weight:Number(f.get('weight')),week:Number(f.get('week'))};previewWeek=state.profile.week||1;save();render();toast('Réglages enregistrés.')}if(form.id==='testForm'){const ex=canonicalExerciseName(String(f.get('ex'))),t={id:form.dataset.id||uid(),ex,exerciseId:exerciseStableId(ex),load:Number(f.get('load')),reps:Number(f.get('reps')),rir:Number(f.get('rir')),bw:Number(f.get('bw')),date:String(f.get('date'))};if(form.dataset.id)state.tests=state.tests.map(old=>old.id===t.id?t:old);else state.tests.push(t);save();closeModal();render();toast('Référence enregistrée.')}if(form.id==='workingForm'){const name=canonicalExerciseName(String(f.get('ex'))),load=Number(f.get('load')),id=exerciseStableId(name);state.workLoadsByExerciseId||={};state.workLoadsByExerciseId[id]=load;state.workLoads||={};for(const legacy of Object.keys(state.workLoads))if(exerciseStableId(legacy)===id)delete state.workLoads[legacy];state.workLoads[name]=load;save();closeModal();render();toast('Charge de travail mise à jour partout dans l’app.')}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();requestWakeLock()}});window.addEventListener('pagehide',()=>{if(state.draft)save()});
// Calendar follows the device's local day. The selected training template is a separate concept.
function todayPlanDay(){const day=new Date().getDay();return day===0?6:day-1}
function fullDateLabel(date=new Date()){const label=date.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});return label[0].toUpperCase()+label.slice(1)}
function syncCalendar(shouldRender){const now=localDate();if(now===calendarKey)return;calendarKey=now;selectionMode='auto';selectedDay=todayPlanDay();if(shouldRender){updateShell();if((tab==='home'||(tab==='workout'&&!state.draft))&&!$('.modal'))render()}}
function thisWeekDates(){const monday=new Date();monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return d})}
function prettySessionTitle(name){const parts=name.split(' + ');return esc(parts[0])+(parts.length>1?'<br><span>+ '+esc(parts.slice(1).join(' + '))+'</span>':'')}
function homeContext(){const active=state.draft,day=active?active.day:selectionMode==='auto'?todayPlanDay():selectedDay,w=active?active.week:state.profile.week,rest=!active&&!sessionMetaForDay(day,w),completed=!active&&selectionMode==='auto'?state.history.filter(h=>localDate(new Date(h.date))===localDate()&&h.week===state.profile.week).sort((a,b)=>new Date(a.date)-new Date(b.date)).at(-1):null;return{active,day,rest,completed}}
function homeHeroHTML(){const {active,day,rest,completed}=homeContext(),meta=active?{name:active.sessionName||program[active.templateDay]?.name||'Séance',focus:active.sessionFocus||program[active.templateDay]?.focus||''}:sessionMetaForDay(day,state.profile.week),manual=selectionMode==='manual'&&!active,plan=active?.exercises||planFor(day,state.profile.week),wk=weeklyHistory(),dates=thisWeekDates(),completedDates=new Set(wk.map(h=>localDate(new Date(h.date)))),target=weeklySessionTarget(state.profile.week);let label=active?'SÉANCE EN COURS':rest?(manual?'JOUR DE REPOS':'AUJOURD’HUI · RÉCUPÉRATION'):manual?'SÉANCE SÉLECTIONNÉE':completed?'SÉANCE DU JOUR TERMINÉE':'SÉANCE DU JOUR';const badge=active?`Commencée le ${dateFr(new Date(active.started).toISOString())}`:rest?WEEKDAYS[day]:manual?`${WEEKDAYS[day]}`:`${WEEKDAYS[day]} ${new Date().getDate()}`;
return `<div class="hero-grid stagger">${completed?completedHomeHTML(completed):`<section class="card session-card ${rest?'rest-card':''}"><span class="session-number" aria-hidden="true">${String(day+1).padStart(2,'0')}</span><div class="row between"><span class="eyebrow orange" id="sessionContext">${label}</span><span class="pill" id="sessionDay">${badge}</span></div><h2 class="session-title">${rest?'RÉCUPÈRE.<br><span>REVIENS FORT.</span>':prettySessionTitle(meta?.name||'Séance')}</h2>${rest?`<p class="rest-description">${WEEKDAYS[day]} est ton jour de repos pour cette semaine.<br>${activeGeneratedProgram()?'Modifie tes disponibilités depuis ton programme Coach.':'Change l’organisation quand tu veux depuis l’onglet Programme.'}</p>`:`<div class="session-meta"><span>${icon('dumbbell')}${plan.length} exercices</span><span>${icon('list')}${active?draftStats().done+' / '+draftStats().total:plan.reduce((n,e)=>n+e.sets.length,0)} séries</span></div>`}<div class="session-footer">${btn(active?'Reprendre ma séance':rest?'Voir les séances':completed?'Voir mon bilan':manual?'Démarrer cette séance':'C’est parti',active?'resume':rest?'chooseSession':completed?'showHistory':'start:'+day,'primary',completed?'check':'arrow')}</div>${manual?`<button class="link-btn today-return" data-action="today">${icon('calendar')}Revenir à aujourd’hui · ${new Date().toLocaleDateString('fr-FR',{weekday:'long'})}</button>`:active?`<p class="micro muted" style="margin-top:14px">${WEEKDAYS[day].toLowerCase()} · tes séries en cours sont conservées.</p>`:''}</section>`}<section class="card week-card"><div class="row between"><h2>Cette semaine</h2><span class="pill">Objectif ${target} séance${target>1?'s':''}</span></div><div class="ring-wrap"><svg viewBox="0 0 192 192" role="img" aria-label="${wk.length} séances sur un objectif de ${target}"><circle class="ring-track" cx="96" cy="96" r="73"/><circle class="ring-progress" cx="96" cy="96" r="73" stroke-dasharray="459" stroke-dashoffset="${459*(1-Math.min(1,wk.length/target))}"/></svg><div class="ring-inner"><b>${wk.length}<small> / ${target}</small></b><span>SÉANCES FAITES</span></div></div><div class="week-strip">${dates.map((date,i)=>{const isRest=!sessionMetaForDay(i,state.profile.week);return `<button class="week-dot ${localDate(date)===localDate()?'today':''} ${completedDates.has(localDate(date))?'completed':''} ${isRest?'rest':''} ${manual&&i===selectedDay?'chosen':''}" data-action="${isRest?'restInfo:'+i:'selectDay:'+i}" aria-label="${fullDateLabel(date)}${isRest?' : récupération':''}" ${localDate(date)===localDate()?'aria-current="date"':''}><span>${date.getDate()}</span><em>${['L','M','M','J','V','S','D'][i]}${completedDates.has(localDate(date))?' ✓':''}</em></button>`}).join('')}</div></section></div>`}
function weekSummaryExtras(){const latest=state.history.at(-1),records=latest?.records||[];if(!records.length)return '';return `<button class="latest-record" data-action="showRecords">${icon('trophy')}<span><b>${records.length} record${records.length>1?'s':''} dans ta dernière séance</b><small>${records.map(r=>esc(r.name)).join(' · ')}</small></span>${icon('chevron')}</button>`}
function showRestDay(day){showModal(WEEKDAYS[day]+' · récupération.',`<p class="small muted">Pas de séance programmée ${WEEKDAYS[day].toLowerCase()} pour cette semaine. Tu peux consulter le programme, choisir une séance manuellement, ou réorganiser ta semaine depuis l’onglet Programme.</p>`,[{label:'Fermer',kind:'outline',fn:closeModal},{label:'Voir les séances',fn:()=>{closeModal();navigate('workout')}}])}
function currentExercise(){return state.draft?.exercises[state.draft.index]}
function exerciseMemoryHTML(ex){const note=state.exerciseNotes?.[ex.name],prior=lastSets(ex.name);return `<div class="exercise-memory"><div class="row between wrap"><button class="link-btn" data-action="exerciseMemory">${icon('history')}${prior.length?'Ma dernière séance':'Historique du mouvement'}</button><button class="link-btn" data-action="exerciseNote">${icon('edit')}${note?'Modifier ma note':'Ajouter un repère'}</button></div>${note?`<p class="exercise-note">${esc(note)}</p>`:''}</div>`}
function exerciseHistoryModal(name){name=canonicalExerciseName(name);const id=exerciseStableId(name),sessions=[...state.history].reverse().filter(h=>h.sets.some(s=>(s.exerciseId||exerciseStableId(s.name))===id)).slice(0,6);const prior=sessions[0]?.sets.filter(s=>(s.exerciseId||exerciseStableId(s.name))===id)||[],record=recordFor(name);showModal(name,`${record?`<div class="exercise-record-head">${icon('trophy')}<div><small>MEILLEURE CHARGE EN SÉANCE</small><b>${fmt(record.load)} kg <span>× ${record.reps} reps</span></b></div></div>`:''}${sessions.length?sessions.map((h,i)=>`<div class="exercise-history-block"><div class="row between"><b>${dateFr(h.date)}</b><span class="micro muted">${i===0?'DERNIÈRE SÉANCE':esc(h.name)}</span></div><div class="past-set-grid"><span>Série</span><span>Charge</span><span>Reps</span><span>RIR</span>${h.sets.filter(s=>(s.exerciseId||exerciseStableId(s.name))===id).map((s,j)=>`<b>${j+1}</b><strong>${fmt(s.load)} kg</strong><b>${s.reps}</b><b>${s.rir}</b>`).join('')}</div></div>`).join(''):empty('history','Aucune séance enregistrée sur ce mouvement.','Tes séries apparaîtront ici après avoir terminé et enregistré ta séance.')}`,prior.length&&currentExercise()?.name===name?[{label:'Fermer',kind:'outline',fn:closeModal},{label:'Reprendre ces charges',fn:()=>{const e=currentExercise();e.sets.forEach((s,i)=>{if(!s.done)s.load=(prior[i]||prior.at(-1)).load});e.calibrated=true;save();closeModal();render();toast('Charges reprises. Les objectifs de reps sont conservés.')}}]:[{label:'Fermer',fn:closeModal}]);}
function exerciseNoteModal(name){showModal('Ton repère sur ce mouvement.',`<form id="exerciseNoteForm" data-exercise="${esc(name)}"><p class="small muted" style="margin-bottom:16px">${esc(name)}</p><label for="exerciseNoteInput">Réglage, placement, détail à retrouver</label><textarea id="exerciseNoteInput" name="note" rows="4" maxlength="1000" placeholder="Siège au cran 4, prise neutre…">${esc(state.exerciseNotes?.[name]||'')}</textarea><p class="micro muted" style="margin-top:12px">Cette note sera retrouvée à chaque séance sur ce mouvement.</p><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">Enregistrer mon repère</button></form>`)}
function saveExerciseNote(form,f){state.exerciseNotes||={};const name=form.dataset.exercise,value=String(f.get('note')).trim();if(value)Object.defineProperty(state.exerciseNotes,name,{value,writable:true,configurable:true,enumerable:true});else delete state.exerciseNotes[name];save();closeModal();render();toast(value?'Repère enregistré.':'Repère supprimé.')}
function exerciseLibraryItems(){
 const map=new Map(),add=(x,source='builtIn')=>{const name=canonicalExerciseName(String(x?.name||'').trim());if(!name)return;const key=normalizedExerciseName(name),exerciseId=x.exerciseId||exerciseStableId(name,state.customExercises);if(!map.has(key))map.set(key,{name,group:String(x.group||'Autres'),equipment:String(x.equipment||''),source,id:x.id||null,exerciseId})};
 EXERCISE_CATALOG.forEach(x=>add(x));
 program.flatMap(p=>p.ex).forEach(x=>add({name:x.name,group:'Programme actuel',equipment:''},'program'));
 Object.values(state.planOverrides||{}).flatMap(week=>Object.values(week||{})).flatMap(list=>Array.isArray(list)?list:[]).forEach(x=>add({name:x.name,group:'Mes exercices',equipment:''},'existing'));
 (state.customExercises||[]).forEach(x=>{const name=canonicalExerciseName(x.name),key=normalizedExerciseName(name);map.set(key,{...x,name,source:'custom',exerciseId:'custom:'+x.id})});
 return [...map.values()].sort((a,b)=>{const ga=EXERCISE_GROUP_ORDER.indexOf(a.group),gb=EXERCISE_GROUP_ORDER.indexOf(b.group),aa=ga<0?999:ga,bb=gb<0?999:gb;return aa-bb||a.group.localeCompare(b.group,'fr')||a.name.localeCompare(b.name,'fr')});
}
function allExerciseNames(){return exerciseLibraryItems().map(x=>x.name)}
function exerciseSelectOptions(selected=''){
 const selectedId=selected?exerciseStableId(selected):'';const groups=new Map();for(const x of exerciseLibraryItems()){if(!groups.has(x.group))groups.set(x.group,[]);groups.get(x.group).push(x)}
 const ordered=[...groups.keys()].sort((a,b)=>{const ia=EXERCISE_GROUP_ORDER.indexOf(a),ib=EXERCISE_GROUP_ORDER.indexOf(b);return (ia<0?999:ia)-(ib<0?999:ib)||a.localeCompare(b,'fr')});
 return `<option value="">Choisir un exercice…</option>`+ordered.map(group=>`<optgroup label="${esc(group)}">${groups.get(group).map(x=>`<option value="${esc(x.name)}" ${x.exerciseId===selectedId?'selected':''}>${esc(x.name)}${x.equipment?' · '+esc(x.equipment):''}</option>`).join('')}</optgroup>`).join('');
}
function exerciseLibraryModal(){const items=exerciseLibraryItems(),custom=(state.customExercises||[]),groups=new Map();for(const x of items.filter(x=>x.source!=='custom')){if(!groups.has(x.group))groups.set(x.group,[]);groups.get(x.group).push(x)}showModal('Bibliothèque d’exercices.',`<div class="row between wrap" style="gap:12px;margin-bottom:18px"><div><b>${items.length} exercices disponibles</b><p class="micro muted" style="margin-top:5px">La liste sert partout où tu ajoutes ou remplaces un mouvement.</p></div><button class="btn btn-primary" data-action="libraryAdd">${icon('plus')}Ajouter un exercice</button></div>${custom.length?`<section class="card" style="padding:16px;margin-bottom:16px"><div class="row between"><b>Mes exercices</b><span class="pill orange">${custom.length}</span></div><div style="margin-top:10px">${custom.map(x=>`<div class="adapt-row"><div class="adapt-name"><b>${esc(x.name)}</b><small>${esc(x.group)}${x.equipment?' · '+esc(x.equipment):''}</small></div><div class="row"><button class="icon-btn" data-action="libraryEdit:${esc(x.id)}" aria-label="Modifier ${esc(x.name)}">${icon('edit')}</button><button class="icon-btn" data-action="libraryDelete:${esc(x.id)}" aria-label="Supprimer ${esc(x.name)}">${icon('trash')}</button></div></div>`).join('')}</div></section>`:''}<div class="stack">${[...groups.entries()].map(([group,list])=>`<details class="card" style="padding:0"><summary style="padding:16px 18px;cursor:pointer" class="row between"><b>${esc(group)}</b><span class="pill">${list.length}</span></summary><div style="padding:0 18px 16px">${list.map(x=>`<div style="padding:10px 0;border-top:1px solid var(--line)"><b class="small">${esc(x.name)}</b>${x.equipment?`<p class="micro muted" style="margin-top:4px">${esc(x.equipment)}</p>`:''}</div>`).join('')}</div></details>`).join('')}</div>`,[{label:'Fermer',fn:closeModal}],true)}
function exerciseLibraryEditor(id=''){const current=(state.customExercises||[]).find(x=>x.id===id),groups=[...EXERCISE_GROUP_ORDER,'Autres'];showModal(current?'Modifier mon exercice.':'Ajouter un exercice à la bibliothèque.',`<form id="exerciseLibraryForm" data-id="${current?esc(current.id):''}"><label for="libraryExerciseName">Nom de l’exercice</label><input id="libraryExerciseName" name="name" maxlength="120" value="${current?esc(current.name):''}" placeholder="Ex. Belt squat pendulaire" required><div class="field-grid" style="margin-top:18px"><div><label for="libraryExerciseGroup">Groupe principal</label><select id="libraryExerciseGroup" name="group" required>${groups.map(g=>`<option value="${esc(g)}" ${g===(current?.group||'Autres')?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div><label for="libraryExerciseEquipment">Matériel</label><input id="libraryExerciseEquipment" name="equipment" maxlength="80" value="${current?esc(current.equipment):''}" placeholder="Machine, poulie, barre…"></div></div><div class="note">Une fois enregistré, cet exercice apparaîtra automatiquement dans les listes de choix de tes séances.</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">${current?'Enregistrer':'Ajouter à la bibliothèque'}</button></form>`)}
function saveExerciseLibraryItem(form,f){const id=form.dataset.id||'',name=String(f.get('name')||'').trim(),group=String(f.get('group')||'Autres').trim(),equipment=String(f.get('equipment')||'').trim();if(!name||name.length>120||!group||group.length>80||equipment.length>80){toast('Vérifie les informations de l’exercice.');return}const duplicate=exerciseLibraryItems().find(x=>x.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr')&&x.id!==id);if(duplicate){toast('Cet exercice existe déjà dans la bibliothèque.');return}state.customExercises||=[];if(id){const i=state.customExercises.findIndex(x=>x.id===id);if(i<0)return;state.customExercises[i]={...state.customExercises[i],name,group,equipment}}else state.customExercises.push({id:uid(),name,group,equipment});save();closeModal();render();toast(id?'Exercice mis à jour.':'Exercice ajouté à la bibliothèque.');exerciseLibraryModal()}
function deleteCustomExercise(id){const x=(state.customExercises||[]).find(e=>e.id===id);if(!x)return;confirmDialog('Supprimer cet exercice de la bibliothèque ?',`<b>${esc(x.name)}</b> ne sera plus proposé dans les listes. Les anciennes séances qui l’utilisent restent intactes.`,()=>{state.customExercises=state.customExercises.filter(e=>e.id!==id);save();render();exerciseLibraryModal();toast('Exercice retiré de la bibliothèque.')},'Supprimer')}

function planEditorModal(day,w){const meta=sessionMetaForDay(day,w);if(!meta){toast('Aucune séance programmée ce jour.');return}planEditContext={day,w};const list=planFor(day,w),custom=hasPlanOverride(w,day);showModal('Modifier '+meta.name+'.',`<p class="small muted" style="margin-bottom:15px">Ajoute, remplace, supprime ou déplace les exercices maintenant. Rien ne démarre : le chrono partira seulement quand tu lanceras la séance.</p><div class="adapt-list">${list.map((e,i)=>`<div class="adapt-row"><span class="adapt-number">${String(i+1).padStart(2,'0')}</span><div class="adapt-name"><b>${esc(e.name)}</b><small>${e.sets.length} séries · ${esc(e.reps)} reps · RIR ${e.rir}</small></div><div class="row"><button class="icon-btn" data-action="planMove:${i},-1" ${i===0?'disabled':''} aria-label="Monter ${esc(e.name)}"><span aria-hidden="true">↑</span></button><button class="icon-btn" data-action="planMove:${i},1" ${i===list.length-1?'disabled':''} aria-label="Descendre ${esc(e.name)}"><span aria-hidden="true">↓</span></button><button class="icon-btn" data-action="planEdit:${i}" aria-label="Modifier ${esc(e.name)}">${icon('edit')}</button><button class="icon-btn" data-action="planRemove:${i}" ${list.length<=1?'disabled':''} aria-label="Retirer ${esc(e.name)}">${icon('trash')}</button></div></div>`).join('')}</div><button class="btn btn-outline btn-wide" data-action="planAdd" style="margin-top:18px">${icon('plus')}Ajouter un mouvement</button>${custom?`<button class="link-btn" data-action="planReset:${w},${day}" style="margin-top:16px">${icon('history')}Revenir au programme prévu</button>`:''}<p class="micro muted" style="margin-top:13px">Ces changements concernent la semaine ${w}, ${WEEKDAYS[day].toLowerCase()}. Ils sont enregistrés avant la séance et synchronisés avec ton carnet.</p>`,[{label:'Terminé',fn:closeModal}],true)}
function detachPlanSuperset(list,tag){if(!tag?.startsWith('superset'))return;list.forEach(e=>{if(e.tag===tag){e.tag='';e.method='Séries classiques';e.plannedCustom=true}})}
function movePlannedExercise(index,delta){if(!planEditContext||!Number.isInteger(index)||!Number.isInteger(delta)||!delta)return;const {day,w}=planEditContext,list=ensurePlanOverride(w,day),target=index+delta;if(index<0||index>=list.length||target<0||target>=list.length)return;detachPlanSuperset(list,list[index].tag);[list[index],list[target]]=[list[target],list[index]];save();render();planEditorModal(day,w)}
function removePlannedExercise(index){if(!planEditContext)return;const {day,w}=planEditContext,list=ensurePlanOverride(w,day),e=list[index];if(!e||list.length<=1)return;detachPlanSuperset(list,e.tag);list.splice(index,1);save();render();toast('Mouvement retiré de cette séance.');planEditorModal(day,w)}
function planExerciseEditor(index){if(!planEditContext)return;const {day,w}=planEditContext,list=ensurePlanOverride(w,day),old=index>=0?list[index]:null,positionMax=old?list.length:list.length+1;showModal(old?'Modifier ce mouvement.':'Ajouter un mouvement.',`<form id="planExerciseEditForm" data-index="${index}"><label for="planExerciseName">Exercice</label><select id="planExerciseName" name="name" required>${exerciseSelectOptions(old?.name||'')}</select><div class="row between wrap" style="margin-top:8px;gap:10px"><p class="micro muted">Choisis dans la bibliothèque complète.</p><button type="button" class="link-btn" data-action="exerciseLibrary">${icon('list')}Ouvrir la bibliothèque</button></div><div class="field-grid" style="margin-top:18px"><div><label for="planSets">Séries</label><input id="planSets" name="sets" type="number" min="1" max="12" step="1" value="${old?.sets.length||3}" required></div><div><label for="planPosition">Position dans la séance</label><input id="planPosition" name="position" type="number" min="1" max="${positionMax}" step="1" value="${old?index+1:list.length+1}" required></div><div><label for="planLoad">Charge proposée · kg</label><input id="planLoad" name="load" type="number" min="0" max="2000" step=".25" value="${old?.loadMode==='manual'&&old?.load!=null?old.load:''}" placeholder="Vide = charge automatique"></div><div><label for="planRir">RIR visé</label><input id="planRir" name="rir" type="number" min="0" max="5" step=".5" value="${old?.rir??2}" required></div><div><label for="planMin">Reps minimum</label><input id="planMin" name="min" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).min:8}" required></div><div><label for="planMax">Reps maximum</label><input id="planMax" name="max" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).max:12}" required></div><div style="grid-column:1/-1"><label for="planRest">Repos entre séries · secondes</label><input id="planRest" name="rest" type="number" min="15" max="900" step="15" value="${old?.rest||90}" required></div></div><label class="bodyweight-choice"><input type="checkbox" name="bodyweight" ${old?.allowZero?'checked':''}>Ce mouvement peut se faire sans charge ajoutée</label><div class="note">Laisse la charge vide pour utiliser automatiquement la charge de travail/progression de cet exercice. Saisis une valeur seulement si tu veux forcer une charge spécifique pour cette séance. La position choisie est enregistrée avant de démarrer.</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">${old?'Enregistrer les modifications':'Ajouter à la séance'}</button></form>`)}
function savePlanExerciseEdit(form,f){if(!planEditContext)return;const {day,w}=planEditContext,index=Number(form.dataset.index),list=ensurePlanOverride(w,day),old=index>=0?list[index]:null,name=String(f.get('name')).trim(),sets=Number(f.get('sets')),position=Number(f.get('position')),loadRaw=String(f.get('load')??'').trim(),load=loadRaw===''?null:Number(loadRaw),min=Number(f.get('min')),max=Number(f.get('max')),rir=Number(f.get('rir')),rest=Number(f.get('rest'));if(!name||['__proto__','constructor','prototype'].includes(name)||name.length>120||!Number.isInteger(sets)||sets<1||sets>12||!Number.isInteger(position)||position<1||position>(old?list.length:list.length+1)||!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>100||min>max||(load!==null&&(!Number.isFinite(load)||load<0||load>2000))||!Number.isFinite(rir)||rir<0||rir>5||!Number.isFinite(rest)||rest<15||rest>900){toast('Vérifie les objectifs du mouvement.');return}if(list.some((e,i)=>i!==index&&exerciseKey(e)===exerciseStableId(name))){toast('Ce mouvement est déjà dans cette séance.');return}if(old?.tag?.startsWith('superset'))detachPlanSuperset(list,old.tag);const allowZero=f.has('bodyweight'),exerciseId=exerciseStableId(name),loadMode=loadRaw===''?'auto':'manual',e={exerciseId,name:canonicalExerciseName(name),sets:Array.from({length:sets},()=>({load,reps:max,rir,min,max,label:'Travail'})),reps:min+'–'+max,rir,tag:'',load,loadMode,rest,tempo:'Contrôlé',method:'Séries personnalisées',calibrated:load!==null&&(load>0||allowZero),allowZero,plannedCustom:true};if(old){list.splice(index,1);const insertAt=Math.max(0,Math.min(list.length,position-1));list.splice(insertAt,0,e)}else{list.splice(Math.max(0,Math.min(list.length,position-1)),0,e)}save();closeModal();render();toast(old?'Mouvement modifié dans le programme.':'Mouvement ajouté au programme.');planEditorModal(day,w)}
function adaptModal(){const d=state.draft;if(!d)return;showModal('Adapte ta séance.',`<p class="small muted" style="margin-bottom:15px">Machine occupée, autre mouvement : ajuste cette séance. Ton programme de base reste disponible.</p><div class="adapt-list">${d.exercises.map((e,i)=>{const done=e.sets.filter(s=>s.done).length;return `<div class="adapt-row"><span class="adapt-number">${String(i+1).padStart(2,'0')}</span><div class="adapt-name"><b>${esc(e.name)}</b><small>${e.sets.length} séries${e.tag.startsWith('superset')?' · '+esc(e.method):''}${done?' · '+done+' validée'+(done>1?'s':''):''}</small></div><div class="row"><button class="icon-btn" data-action="swapExercise:${i}" ${done?'disabled':''} aria-label="Remplacer ${esc(e.name)}">${icon('edit')}</button><button class="icon-btn" data-action="removeExercise:${i}" ${done||d.exercises.length<=1?'disabled':''} aria-label="Retirer ${esc(e.name)}">${icon('trash')}</button></div></div>`}).join('')}</div><button class="btn btn-outline btn-wide" data-action="addExercise" style="margin-top:18px">${icon('plus')}Ajouter un mouvement</button><p class="micro muted" style="margin-top:13px">Un mouvement avec une série validée est conservé dans ta séance.</p>`,[{label:'Retour à ma séance',fn:closeModal}],true)}
function exerciseEditor(index){const d=state.draft;if(!d)return;const old=index>=0?d.exercises[index]:null;if(old?.sets.some(s=>s.done)){toast('Conserve ce mouvement : des séries sont déjà validées.');return}showModal(old?'Choisir un autre mouvement.':'Ajouter un mouvement.',`<form id="exerciseEditForm" data-index="${index}"><label for="customExerciseName">Exercice</label><select id="customExerciseName" name="name" required>${exerciseSelectOptions(old?.name||'')}</select><div class="row between wrap" style="margin-top:8px;gap:10px"><p class="micro muted">Choisis dans la bibliothèque complète.</p><button type="button" class="link-btn" data-action="exerciseLibrary">${icon('list')}Ouvrir la bibliothèque</button></div><div class="field-grid" style="margin-top:18px"><div><label for="customSets">Séries</label><input id="customSets" name="sets" type="number" min="1" max="12" step="1" value="${old?.sets.length||3}" ${old?.tag.startsWith('superset')?'readonly':''} required></div><div><label for="customLoad">Charge / lest · kg</label><input id="customLoad" name="load" type="number" min="0" max="2000" step=".25" value="${old?.load==null?'':old.load}" placeholder="Vide = à calibrer"></div><div><label for="customMin">Reps minimum</label><input id="customMin" name="min" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).min:8}" required></div><div><label for="customMax">Reps maximum</label><input id="customMax" name="max" type="number" min="1" max="100" step="1" value="${old?repRange(old.reps).max:12}" required></div><div><label for="customRir">RIR visé</label><input id="customRir" name="rir" type="number" min="0" max="5" step=".5" value="${old?.rir??2}" required></div><div><label for="customRest">Repos · secondes</label><input id="customRest" name="rest" type="number" min="15" max="900" step="1" value="${old?.rest||90}" required></div></div><label class="bodyweight-choice"><input type="checkbox" name="bodyweight">Ce mouvement peut se faire sans charge ajoutée</label><div class="note">${old?.tag.startsWith('superset')?'Le mouvement garde sa place dans le superset. Le nombre de séries reste identique à celui du partenaire.':'Les objectifs sont ceux que tu choisis pour cette séance.'}</div><button type="submit" class="btn btn-primary btn-wide" style="margin-top:20px">${old?'Remplacer le mouvement':'Ajouter à ma séance'}</button></form>`)}
function saveExerciseEdit(form,f){const d=state.draft;if(!d)return;const index=Number(form.dataset.index),old=index>=0?d.exercises[index]:null;if(old?.sets.some(s=>s.done)){toast('Ce mouvement contient une série validée.');return}const name=String(f.get('name')).trim(),sets=Number(f.get('sets')),rawLoad=String(f.get('load')??'').trim(),load=rawLoad===''?0:Number(rawLoad),min=Number(f.get('min')),max=Number(f.get('max')),rir=Number(f.get('rir')),rest=Number(f.get('rest'));
if(!name||['__proto__','constructor','prototype'].includes(name)||name.length>120||!Number.isInteger(sets)||sets<1||sets>12||!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>100||min>max||!Number.isFinite(load)||load<0||load>2000||!Number.isFinite(rir)||rir<0||rir>5||!Number.isFinite(rest)||rest<15||rest>900){toast('Vérifie les objectifs du mouvement.');return}if(d.exercises.some((e,i)=>i!==index&&exerciseKey(e)===exerciseStableId(name))){toast('Ce mouvement est déjà dans ta séance.');return}if(old?.tag.startsWith('superset')&&sets!==old.sets.length){toast('Conserve le même nombre de séries pour la paire.');return}const tag=old?.tag.startsWith('superset')?old.tag:'',exerciseId=exerciseStableId(name),e={exerciseId,name:canonicalExerciseName(name),sets:Array.from({length:sets},()=>({load,reps:max,rir,min,max,label:'Travail',done:false})),reps:min+'–'+max,rir,tag,load,rest,tempo:'Contrôlé',method:tag?tag.replace('superset','Superset'):'Séries personnalisées',calibrated:load>0||f.has('bodyweight'),allowZero:f.has('bodyweight'),manual:true};if(old){d.exercises[index]=e;d.index=index}else{d.exercises.push(e);d.index=d.exercises.length-1}d.rest=null;save();closeModal();render();toast(old?'Mouvement remplacé pour cette séance.':'Mouvement ajouté.');}
function removeExercise(index){const d=state.draft,e=d?.exercises[index];if(!e||e.sets.some(s=>s.done)||d.exercises.length<=1)return;confirmDialog('Retirer ce mouvement ?',`<b>${esc(e.name)}</b> sera retiré de cette séance.${e.tag.startsWith('superset')?' Son partenaire continuera en séries classiques.':''}`,()=>{const active=d.exercises[d.index];d.exercises.splice(index,1);d.exercises.forEach(x=>{if(e.tag.startsWith('superset')&&x.tag===e.tag){x.tag='';x.method='Séries classiques';x.manual=true}});d.index=Math.max(0,d.exercises.indexOf(active));d.rest=null;save();render();adaptModal()},'Retirer')}
function changeSetCount(delta){const d=state.draft,e=currentExercise();if(!e)return;const pair=e.tag.startsWith('superset')?d.exercises.filter(x=>x.tag===e.tag):[e];if(delta>0){if(pair.some(x=>x.sets.length>=12)){toast('Maximum 12 séries par mouvement.');return}pair.forEach(x=>{const last=x.sets.at(-1);x.sets.push({...last,done:false,label:'Ajoutée'});x.manual=true})}else{if(pair.some(x=>x.sets.length<=1||x.sets.at(-1).done)){toast('Seule une dernière série non validée peut être retirée.');return}pair.forEach(x=>{x.sets.pop();x.manual=true})}save();render();toast(pair.length>1?(delta>0?'Une paire de séries ajoutée au superset.':'Une paire de séries retirée.'):(delta>0?'Une série ajoutée.':'Une série retirée.'))}
function recordFor(name,history=state.history){const id=exerciseStableId(name);let best=null;for(const h of history)for(const s of h.sets){if((s.exerciseId||exerciseStableId(s.name))!==id)continue;if(!best||s.load>best.load||(s.load===best.load&&s.reps>best.reps))best={name:canonicalExerciseName(s.name||name),exerciseId:id,load:s.load,reps:s.reps,date:h.date,session:h.id}}return best}
function allRecords(){const ids=[...new Set(state.history.flatMap(h=>h.sets.map(s=>s.exerciseId||exerciseStableId(s.name))))];return ids.map(id=>recordFor(exerciseNameForId(id))).filter(Boolean).sort((a,b)=>new Date(b.date)-new Date(a.date)||a.name.localeCompare(b.name,'fr'))}
function detectRecords(sets,history){const records=[];const ids=[...new Set(sets.map(s=>s.exerciseId||exerciseStableId(s.name)))];for(const id of ids){const sample=sets.find(s=>(s.exerciseId||exerciseStableId(s.name))===id),name=canonicalExerciseName(sample?.name||exerciseNameForId(id)),previous=recordFor(name,history);if(!previous)continue;const best=sets.filter(s=>(s.exerciseId||exerciseStableId(s.name))===id).sort((a,b)=>b.load-a.load||b.reps-a.reps)[0];if(best.load>previous.load||(best.load===previous.load&&best.reps>previous.reps))records.push({name,exerciseId:id,load:best.load,reps:best.reps,previousLoad:previous.load,previousReps:previous.reps})}return records}
function recordCelebrationHTML(records){return records.length?`<section class="record-celebration"><div class="row">${icon('trophy')}<b>${records.length} nouveau${records.length>1?'x':''} record${records.length>1?'s':''} en séance</b></div>${records.map(r=>`<div class="row between"><span>${esc(r.name)}</span><strong>${fmt(r.load)} kg × ${r.reps}</strong></div>`).join('')}</section>`:''}
function recordsView(){const records=allRecords();return `<section class="card"><div class="row between card-head"><h2>Tes meilleures séries.</h2><span class="pill orange">${icon('trophy')}${records.length} mouvement${records.length>1?'s':''}</span></div><p class="small muted" style="margin-top:12px">La plus lourde charge validée en séance. À charge égale, le meilleur nombre de répétitions.</p>${records.length?`<div class="records-grid">${records.map(r=>`<button class="record-card" data-action="exerciseMemory:${esc(r.name)}"><div class="row between">${icon('trophy')}<small>${dateFr(r.date)}</small></div><h3>${esc(r.name)}</h3><b>${fmt(r.load)}<small> kg</small></b><p>× ${r.reps} répétitions${r.name==='Tractions lestées'?' · lest ajouté':''}</p><span class="record-open">Voir mes séries ${icon('up')}</span></button>`).join('')}</div>`:empty('trophy','Tes records se construisent à la salle.','Enregistre une première séance pour créer tes repères. Les séances suivantes pourront battre ces références.')}<div class="note" style="margin-top:20px">Ces records viennent de tes séries réellement enregistrées. Ils sont séparés des tests de force et des estimations de 1RM.</div></section>`}

// One presentation of saved results, shared by cards, history and the final recap.
// Counts always come from recorded sets; old backups without targets stay neutral.
function resultStats(h){
 const sets=Array.isArray(h.sets)?h.sets:[],done=sets.length;
 const raw=Number(h.completion?.total),known=Number.isInteger(raw)&&raw>0&&raw>=done;
 const total=known?raw:null,full=known&&done===total;
 return {done,total,full,ratio:known?done/total:null,remaining:known?total-done:null,
  exercises:new Set(sets.map(s=>s.name)).size,volume:workload(sets),reps:sets.reduce((n,s)=>n+s.reps,0),
  minutes:h.duration>0?Math.max(1,Math.round(h.duration/60)):null,
  label:full?'Complète':known?'Partielle':'Enregistrée'};
}
function resultGroups(h){
 const actual=[...new Set(h.sets.map(s=>s.name))],metadata=Array.isArray(h.exercises)?h.exercises:[];
 const names=[...new Set([...metadata.map(e=>e.name),...actual])];
 return names.map(name=>{const sets=h.sets.filter(s=>s.name===name),e=metadata.find(e=>e.name===name),total=Number.isInteger(e?.total)&&e.total>=sets.length?e.total:null;return {name,sets,total}});
}
function resultDate(h){return new Date(h.date).toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}
function resultVolume(h){const n=resultStats(h).volume;return n>=1000?{value:fmt(n/1000,2),unit:'t'}:{value:fmt(n,0),unit:'kg'}}
function resultRing(h){const s=resultStats(h),n=s.ratio==null?null:Math.round(s.ratio*100);return `<div class="result-ring ${s.full?'is-full':''}" role="img" aria-label="${s.total?s.done+' séries validées sur '+s.total:s.done+' séries enregistrées'}"><svg viewBox="0 0 80 80" aria-hidden="true"><circle class="result-ring-track" cx="40" cy="40" r="34"/><circle class="result-ring-fill" cx="40" cy="40" r="34" stroke-dasharray="213.63" stroke-dashoffset="${s.ratio==null?0:213.63*(1-s.ratio)}"/></svg><span>${s.full?icon('check'):n==null?icon('check'):`<b>${n}<small>%</small></b>`}</span></div>`}
function resultMetrics(h){const s=resultStats(h),v=resultVolume(h);return `<div class="result-metrics"><div><span>${icon('list')}Séries validées</span><strong>${s.done}${s.total?`<small> / ${s.total}</small>`:''}</strong></div><div><span>${icon('clock')}Durée</span><strong>${s.minutes??'—'}${s.minutes?'<small> min</small>':''}</strong></div><div><span>${icon('weight')}Volume saisi</span><strong>${v.value}<small> ${v.unit}</small></strong></div></div>`}
function compactResults(h){return `<div class="result-exercise-list">${resultGroups(h).filter(e=>e.sets.length).map(e=>{const best=[...e.sets].sort((a,b)=>b.load-a.load||b.reps-a.reps)[0];return `<div class="result-exercise"><span class="result-tick">${icon('check')}</span><div><b>${esc(e.name)}</b><p>${e.sets.length} série${e.sets.length>1?'s':''} validée${e.sets.length>1?'s':''}${e.total?' / '+e.total:''}</p></div><span class="result-best">${fmt(best.load)}<small> kg</small><em>× ${best.reps} reps</em></span></div>`}).join('')}</div>`}
function resultProgress(h){const s=resultStats(h);return `<div class="result-progress"><div><span>${s.full?'Tout le programme a été validé.':s.total?`${s.remaining} série${s.remaining>1?'s':''} non validée${s.remaining>1?'s':''}`:'Objectif initial non renseigné'}</span><b>${s.label}</b></div>${s.total?`<div class="result-track"><i style="width:${s.ratio*100}%"></i></div>`:''}</div>`}
function resultStatus(h){const s=resultStats(h);return `<span class="result-status ${s.full?'is-full':''}">${icon('check')}SÉANCE ENREGISTRÉE</span>`}
function latestDayResult(day,w){if(!sessionMetaForDay(day,w))return null;return state.history.filter(h=>h.week===w&&h.day===day).sort((a,b)=>new Date(b.date)-new Date(a.date))[0]||null}
function completedDayHTML(h,day,w){const s=resultStats(h);return `<details class="day-card result-card ${s.full?'is-full':''}" data-result-id="${esc(h.id)}"><summary><div class="result-top"><span class="eyebrow">${WEEKDAYS[day]}</span>${resultStatus(h)}</div><div class="result-title-row"><div><p class="result-caption">BILAN DU ${resultDate(h)}</p><h2 class="day-title">${esc(h.name)}</h2></div>${resultRing(h)}</div>${resultMetrics(h)}${resultProgress(h)}<div class="result-card-footer"><span>Explorer mon bilan</span>${icon('arrow','result-open-icon')}</div></summary><div class="day-detail result-card-detail"><div class="result-section-heading"><span>CE QUE TU AS RÉALISÉ</span><small>Meilleure série par charge</small></div>${compactResults(h)}<button class="btn btn-primary btn-wide" data-action="showRecap:${esc(h.id)}">Ouvrir le bilan complet ${icon('up')}</button><button class="link-btn result-replay" data-action="repeatResult:${esc(h.id)}">${icon('plus')}Démarrer une nouvelle séance</button></div></details>`}
function programDayHTML(i,w){const meta=sessionMetaForDay(i,w),dayName=WEEKDAYS[i];if(!meta)return `<div class="day-card rest-day-card"><div class="day-head"><span class="eyebrow" style="color:var(--blue)">${dayName}</span><span class="pill">Repos</span></div><span class="day-code" aria-hidden="true">0${i+1}</span><h2 class="day-title">RÉCUPÉRATION</h2><p class="day-sub">Aucune séance programmée ce jour, pour cette semaine.</p><div class="spacer"></div><button class="link-btn" data-action="${activeGeneratedProgram()?'coachSetup':'organizeWeek'}">${icon('edit')}${activeGeneratedProgram()?'Modifier mes jours':'Y mettre une séance'}</button></div>`;const done=latestDayResult(i,w);if(done)return completedDayHTML(done,i,w);const plans=planFor(i,w),custom=hasPlanOverride(w,i);return `<details class="day-card"><summary><div class="day-head"><span class="eyebrow" style="color:${i%3===0?'var(--orange)':i%3===1?'var(--blue)':'var(--pink)'}">${dayName}</span><span class="pill ${custom||meta.generated?'orange':''}">${custom?'Personnalisée · ':meta.generated?'Coach · ':''}${plans.length} exercices</span></div><span class="day-code" aria-hidden="true">0${i+1}</span><h2 class="day-title">${esc(meta.name)}</h2><p class="day-sub">${esc(meta.focus)}</p><div class="day-bottom"><span class="small muted">${plans.reduce((n,e)=>n+e.sets.length,0)} séries · ${plans.some(e=>e.tag?.startsWith('superset'))?'Supersets bras':'Séries classiques'}</span>${icon('chevron','chevron')}</div></summary><div class="day-detail">${plans.map(e=>`<div class="plan-ex"><div class="row between"><b>${esc(e.name)}</b><span class="suggested">${e.load==null?'À régler':fmt(e.load)+' kg'}</span></div><p>${e.sets.length} × ${e.reps} · RIR ${e.rir} · ${esc(e.method)}</p>${e.method.includes('back-off')?`<p>${e.sets.map(s=>s.label+' '+s.reps+' reps'+(s.load==null?'':' à '+fmt(s.load)+' kg')).join(' · ')}</p>`:''}</div>`).join('')}<div class="spacer"></div><div class="stack">${btn('Modifier / réorganiser','editPlan:'+i,'outline','edit')}${btn(w===state.profile.week?'Démarrer la séance':'Utiliser cette semaine','startPreview:'+i,'primary','arrow')}</div></div></details>`}
function completedHomeHTML(h){const s=resultStats(h);return `<section class="card result-home ${s.full?'is-full':''}"><div class="result-top">${resultStatus(h)}<span class="result-date">${resultDate(h)}</span></div><div class="result-title-row"><div><p class="result-caption">${s.full?'TU AS TENU LE CAP.':'CHAQUE SÉRIE COMPTE.'}</p><h2 class="result-home-title">${s.full?'MISSION<br><span>ACCOMPLIE.</span>':'DU TRAVAIL.<br><span>DU PROGRÈS.</span>'}</h2></div>${resultRing(h)}</div><p class="result-home-session">${esc(h.name)}</p>${resultMetrics(h)}${resultProgress(h)}<button class="btn btn-primary btn-wide" data-action="showRecap:${esc(h.id)}">Voir mon bilan ${icon('arrow')}</button></section>`}
function resultExerciseDetails(h){const groups=resultGroups(h),done=groups.filter(e=>e.sets.length),missed=groups.filter(e=>!e.sets.length);return `<section class="recap-section"><div class="result-section-heading"><h3>Ton travail, série par série.</h3><span>${done.length} exercice${done.length>1?'s':''}</span></div><div class="recap-exercises">${done.map((e,i)=>`<details class="recap-exercise" ${done.length===1?'open':''}><summary><span class="recap-ex-index">${String(i+1).padStart(2,'0')}</span><div><b>${esc(e.name)}</b><p>${e.sets.length}${e.total?' / '+e.total:''} séries validées · ${fmt(workload(e.sets),0)} kg de volume</p></div>${icon('chevron')}</summary><div class="recap-table"><div class="recap-table-head"><span>SÉRIE</span><span>CHARGE</span><span>REPS</span><span>RIR</span></div>${e.sets.map((s,index)=>`<div><span><i>${icon('check')}</i>${s.n||index+1}</span><strong>${fmt(s.load)}<small> kg</small></strong><strong>${s.reps}</strong><span>${s.rir??'—'}</span></div>`).join('')}</div></details>`).join('')}</div>${missed.length?`<details class="recap-missed"><summary>${missed.length} exercice${missed.length>1?'s':''} sans série validée ${icon('chevron')}</summary><p>${missed.map(e=>esc(e.name)).join(' · ')}</p></details>`:''}</section>`}
function resultBodyHTML(h,mode='saved'){
 const s=resultStats(h),saved=mode!=='preview',title=s.full?'MISSION<br><span>ACCOMPLIE.</span>':'CHAQUE SÉRIE<br><span>COMPTE.</span>';
 return `<div class="recap-hero"><div class="result-top"><span class="result-status ${s.full?'is-full':''}">${icon(saved?'check':'save')}${saved?'SAUVEGARDÉE DANS TON CARNET':'PRÊTE À ÊTRE ENREGISTRÉE'}</span><span class="result-date">${resultDate(h)}</span></div><div class="recap-hero-layout"><div><h2 class="recap-big-title">${title}</h2><p class="recap-session-name">${esc(h.name)}</p><p class="recap-subline">${h.week!=null?'Semaine '+h.week+' · ':''}${s.exercises} exercice${s.exercises>1?'s':''} réalisé${s.exercises>1?'s':''} · ${s.label.toLowerCase()}</p></div>${resultRing(h)}</div>${resultMetrics(h)}${resultProgress(h)}</div>${saved&&h.records?.length?`<section class="recap-records"><div class="result-section-heading"><h3>${icon('trophy')}${h.records.length} record${h.records.length>1?'s':''} battu${h.records.length>1?'s':''}</h3></div>${h.records.map(r=>`<div><b>${esc(r.name)}</b><strong>${fmt(r.load)} kg <span>× ${r.reps}</span></strong></div>`).join('')}</section>`:''}${resultExerciseDetails(h)}${saved&&h.note?`<section class="recap-note"><span class="eyebrow">TON RESSENTI</span><p>${esc(h.note)}</p></section>`:''}${saved&&h.suggestions?.length?`<details class="recap-next"><summary><span>${icon('arrow')}Pour la prochaine fois</span>${icon('chevron')}</summary><p class="micro muted">Charges de travail proposées lors de l’enregistrement de cette séance. Elles restent ajustables.</p>${h.suggestions.map(x=>`<div class="suggestion"><div><b>${esc(x.name)}</b><p>${esc(x.reason)}</p></div><strong>${fmt(x.load)} kg</strong></div>`).join('')}</details>`:''}<p class="recap-footnote">Volume saisi = charge × répétitions des séries validées. Haltères : charge d’un haltère ; tractions : lest ajouté.</p>`;
}
function presentRecap(h,mode='saved'){
 const preview=mode==='preview';let html=resultBodyHTML(h,mode);
 if(preview)html+=`<section class="recap-note-input"><label for="workoutNote">Comment tu t’es senti ? <span class="muted">Facultatif</span></label><textarea id="workoutNote" rows="2" maxlength="500" placeholder="Bonne énergie, une série difficile, un réglage à garder…"></textarea><p class="micro muted">${resultStats(h).remaining>0?'Seules tes '+h.sets.length+' séries validées seront enregistrées.':'Tes séries sont prêtes à rejoindre ton historique.'}</p></section>`;
 showModal(preview?'Dernier regard avant de valider.':'Ton bilan de séance.',html,preview?[{label:'Revenir à la séance',kind:'outline',fn:closeModal},{label:'Enregistrer la séance',fn:commitWorkout}]:[{label:'Fermer le bilan',fn:closeModal}],true);
 const modal=$('.modal');modal.classList.add('recap-modal');modal.dataset.resultMode=mode;modal.scrollTop=0;
}
function showSessionRecap(id){const h=state.history.find(x=>x.id===id);if(h)presentRecap(h)}
function draftResult(){const d=state.draft;if(!d)return null;const sets=d.exercises.flatMap(e=>e.sets.filter(s=>s.done).map(s=>({exerciseId:exerciseKey(e),name:canonicalExerciseName(e.name),n:e.sets.indexOf(s)+1,load:s.load,reps:s.reps,rir:s.rir}))),exercises=d.exercises.map(e=>({exerciseId:exerciseKey(e),name:canonicalExerciseName(e.name),done:e.sets.filter(s=>s.done).length,total:e.sets.length}));return {id:d.id,date:new Date().toISOString(),day:d.day,templateDay:d.templateDay,name:d.sessionName||program[d.templateDay]?.name||'Séance',generatedSessionId:d.generatedSessionId||null,coachProgramId:d.coachProgramId||null,week:d.week,bodyWeight:d.bodyWeight,duration:Math.max(0,Math.floor((Date.now()-d.started)/1000)),sets,exercises,completion:{done:sets.length,total:exercises.reduce((n,e)=>n+e.total,0)}}}
function finishWorkout(){const h=draftResult();if(!h)return;if(!h.sets.length){toast('Valide au moins une série avant de terminer.');return}presentRecap(h,'preview')}
function commitWorkout(){const d=state.draft;if(!d)return;const h=draftResult();if(!h?.sets.length)return;h.note=$('#workoutNote')?.value||'';h.suggestions=d.exercises.map(nextSuggestion).filter(Boolean);h.records=detectRecords(h.sets,state.history);const old=clone(state);if(state.history.some(x=>x.id===h.id)){toast('Cette séance est déjà enregistrée.');return}state.history.push(h);state.workLoadsByExerciseId||={};const progressionEvents=[];h.suggestions.forEach(s=>{const id=s.exerciseId||exerciseStableId(s.name),name=canonicalExerciseName(s.name),previous=state.workLoadsByExerciseId[id]??workingLoadEntries().find(x=>x.exerciseId===id)?.load??null;if(window.MuscuCoachStorage){const active=window.MuscuCoachStorage.activeProgramFromNotebook(state);progressionEvents.push(window.MuscuCoachStorage.appendProgressionEventInNotebook(state,{programId:active?.id||null,exerciseId:id,type:s.change>0?'increase':s.change<0?'reduce':'maintain',previousLoadKg:previous,nextLoadKg:s.load,changeKg:s.change,reason:s.reason,sessionId:h.id,weekNumber:h.week,source:'completed_session'}))}for(const legacy of Object.keys(state.workLoads||{}))if(exerciseStableId(legacy)===id)delete state.workLoads[legacy];state.workLoads[name]=s.load;state.workLoadsByExerciseId[id]=s.load});state.draft=null;if(!save()){state=old;toast('Enregistrement impossible. Ta séance reste ouverte : exporte ton carnet pour la conserver.');return}progressionEvents.forEach(event=>void window.MuscuCoachStorage?.saveProgressionEventRemote(event).catch(err=>console.warn('Progression Supabase non synchronisée',err)));previewWeek=h.week;releaseWake();closeModal();navigate('home');presentRecap(h,'saved');celebrate()}
function repeatResult(id){const h=state.history.find(x=>x.id===id);if(!h)return;confirmDialog('Commencer une nouvelle séance ?', 'Ton bilan reste enregistré. Une nouvelle séance sera créée à partir du programme actuellement prévu pour ce jour.',()=>startWorkout(h.day,h.week??state.profile.week),'Démarrer une nouvelle séance')}


function coachingCatalogSnapshot(){return exerciseLibraryItems().map(x=>({exerciseId:x.exerciseId,name:x.name,group:x.group||'',equipment:x.equipment||'',source:x.source||'catalog'}))}
function validateMassGainGenerationInput(input){if(!window.MuscuCoachDomain)throw Error('Moteur de schémas indisponible.');return window.MuscuCoachDomain.validateMassGainGenerationInput(input)}
function queueCoachRemote(promise,label){if(!promise?.catch)return;void promise.catch(err=>console.warn(label||'Synchronisation coaching Supabase impossible',err))}
function generateMassGainProgram(input,{persist=false}={}){if(!window.MuscuCoachEngine||!window.MuscuCoachStorage)throw Error('Moteur de coaching indisponible.');const program=window.MuscuCoachEngine.generateMassGainProgram(input,{catalog:coachingCatalogSnapshot()});if(persist&&program?.status==='generated'){window.MuscuCoachStorage.saveProgramInNotebook(state,program,{activate:true,input});if(!save())throw Error('Programme généré mais sauvegarde locale impossible.');queueCoachRemote(window.MuscuCoachStorage.saveProgramRemote(program),'Programme Supabase non synchronisé');render();}return program}
function saveCoachWeeklyReview(review){if(!window.MuscuCoachStorage)throw Error('Stockage coaching indisponible.');const saved=window.MuscuCoachStorage.saveWeeklyReviewInNotebook(state,review);if(!save())throw Error('Bilan créé mais sauvegarde locale impossible.');queueCoachRemote(window.MuscuCoachStorage.saveWeeklyReviewRemote(saved),'Bilan Supabase non synchronisé');return saved}
function recordCoachProgressionEvent(event){if(!window.MuscuCoachStorage)throw Error('Stockage coaching indisponible.');const saved=window.MuscuCoachStorage.appendProgressionEventInNotebook(state,event);if(!save())throw Error('Événement créé mais sauvegarde locale impossible.');queueCoachRemote(window.MuscuCoachStorage.saveProgressionEventRemote(saved),'Progression Supabase non synchronisée');return saved}
async function syncCoachingRelational(){if(!window.MuscuCoachStorage)return {status:'unavailable'};const result=await window.MuscuCoachStorage.reconcileNotebookWithSupabase(state);if(result.changed){if(activeGeneratedProgram()&&previewWeek<1)previewWeek=1;save();render()}return result}
window.MuscuCoachAppAPI=Object.freeze({version:'1.2.0',openCoachSetup:coachSetupModal,getExerciseCatalog:coachingCatalogSnapshot,validateMassGainGenerationInput,generateMassGainProgram,getActiveGeneratedProgram:()=>window.MuscuCoachStorage?.activeProgramFromNotebook(state)||null,saveWeeklyReview:saveCoachWeeklyReview,recordProgressionEvent:recordCoachProgressionEvent,syncCoachingRelational});

shell();if(TABINFO.some(t=>t[0]===location.hash.slice(1)))tab=location.hash.slice(1);render();setInterval(tick,500);
